// pi-ai-summary — one-line collapsed rows for Pi tool calls and thinking,
// plus a CNY display variant of the native footer.
//
// Architecture (v1):
//   public events → read-only state → pure summary builders →
//     Adapter 1: ToolExecutionComponent.render  (collapsed summary / native when expanded)
//     Adapter 2: AssistantMessageComponent.updateContent (hidden-thinking label decoration)
//     Footer: ctx.ui.setFooter() (public API, NOT a prototype patch;
//       native rendering logic re-implemented, only cost shown in ¥)
//
// No timers, no polling, no Container patching, no component moves, no
// modification of tool args/results or session messages. Ctrl+O (expanded)
// and visible thinking always render through Pi's native renderer.

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { installCnyFooter, uninstallCnyFooter } from "./src/footer-cny.ts";
import {
  installThinkingLabelAdapter,
  uninstallThinkingLabelAdapter,
} from "./src/adapters/thinking-label.ts";
import {
  installToolRenderAdapter,
  uninstallToolRenderAdapter,
} from "./src/adapters/tool-render.ts";
import { registerEventHandlers } from "./src/events.ts";
import { createSessionState, type SessionState } from "./src/state.ts";
import type { ThemeLike } from "./src/theme.ts";

export default function (pi: ExtensionAPI) {
  const state: SessionState = createSessionState();
  let themeProvider: (() => ThemeLike | undefined) | undefined;
  let cwdProvider: (() => string | undefined) | undefined;
  // Captured from ctx.isProjectTrusted() on each session_start; gates the
  // project-level settings read in the thinking-label adapter.
  let projectTrusted = false;
  let toolAdapterInstalled = false;
  let thinkingAdapterInstalled = false;
  let footerInstalled = false;

  registerEventHandlers(pi, state);

  pi.on("session_start", (_event, ctx: ExtensionContext) => {
    const mode = (ctx as { mode?: unknown }).mode;
    const ui = (ctx as { ui?: { theme?: ThemeLike } }).ui;
    themeProvider = () => ui?.theme;
    cwdProvider = () => (ctx as { cwd?: string }).cwd ?? process.cwd();
    // Unknown shape → false (conservative: skip project settings, global
    // chain still applies). Any probe failure → false; must not break the
    // session_start handler before the adapters install.
    try {
      projectTrusted =
        (ctx as { isProjectTrusted?: () => boolean }).isProjectTrusted?.() ?? false;
    } catch {
      projectTrusted = false;
    }
    if (mode !== "tui") return;

    // Single instance only. Repeated session_start on this instance is
    // harmless; /reload shuts down the old instance before installing anew.
    // A rejected second instance must never uninstall the first one's patch.
    if (!toolAdapterInstalled) {
      toolAdapterInstalled = installToolRenderAdapter(() => themeProvider?.(), state);
      if (!toolAdapterInstalled) {
        // notify is best-effort UX: optional-chained so a missing ui/notify
        // (e.g. fake/test contexts) can never break the session_start handler.
        ctx.ui?.notify?.("[PI_AI_SUMMARY_INSTALL_FAILED] tool adapter: already installed or incompatible prototype; single instance only.", "error");
      }
    }
    if (!thinkingAdapterInstalled) {
      thinkingAdapterInstalled = installThinkingLabelAdapter(
        () => cwdProvider?.(),
        () => projectTrusted,
        () => themeProvider?.(),
        () => state.finalAnswerRef?.deref(),
      );
      if (!thinkingAdapterInstalled) {
        ctx.ui?.notify?.("[PI_AI_SUMMARY_INSTALL_FAILED] thinking adapter: already installed or incompatible prototype; single instance only.", "error");
      }
    }
    if (!footerInstalled) {
      footerInstalled = installCnyFooter(
        ctx as unknown as Parameters<typeof installCnyFooter>[0],
        () => state.generation,
      );
      if (!footerInstalled) {
        ctx.ui?.notify?.("[PI_AI_SUMMARY_INSTALL_FAILED] footer: setFooter unavailable; native USD footer retained.", "error");
      }
    }
  });

  pi.on("session_shutdown", (_event, ctx) => {
    if (footerInstalled) {
      const ok = uninstallCnyFooter(ctx as unknown as Parameters<typeof uninstallCnyFooter>[0]);
      // setFooter(undefined) restores the native footer; a failure only means
      // the native footer may be retained by another owner — never fatal.
      if (!ok) {
        ctx.ui?.notify?.("[PI_AI_SUMMARY_UNINSTALL_CONFLICT] footer retained: setFooter restore failed.", "error");
      }
      footerInstalled = !ok;
    }
    if (toolAdapterInstalled) {
      toolAdapterInstalled = !uninstallToolRenderAdapter();
      if (toolAdapterInstalled) {
        ctx.ui?.notify?.("[PI_AI_SUMMARY_UNINSTALL_CONFLICT] tool adapter retained: another extension changed its methods. Restart Pi after resolving the conflict.", "error");
      }
    }
    if (thinkingAdapterInstalled) {
      thinkingAdapterInstalled = !uninstallThinkingLabelAdapter();
      if (thinkingAdapterInstalled) {
        ctx.ui?.notify?.("[PI_AI_SUMMARY_UNINSTALL_CONFLICT] thinking adapter retained: another extension changed its methods. Restart Pi after resolving the conflict.", "error");
      }
    }
    themeProvider = undefined;
    cwdProvider = undefined;
    projectTrusted = false;
  });
}

