extensions.pi-ai-summary/src/footer-cny.ts:
/**
 * footer-cny — 原生页脚的 CNY 显示版（cny-footer 合并入 pi-ai-summary）。
 *
 * 做法：用公开 API `ctx.ui.setFooter()` 接管页脚，按原生 FooterComponent
 * （0.99.1，dist/modes/interactive/components/footer.js）的渲染逻辑逐项
 * 复刻，唯一改动是成本显示：`$0.015` → `¥0.11`（USD → CNY，固定汇率）。
 * 复刻基线已对齐 0.99.1（2026-09-30 实测核对，见根 CHANGELOG 同日条目）。
 *
 * 注意这不是第三个 prototype patch：不碰任何组件原型，只用公开的
 * setFooter(factory | undefined) API；卸载即 `setFooter(undefined)` 恢复原生。
 * Pi 内部成本仍是 USD，本模块只改显示，不影响 /session、日志与结算。
 *
 * 已知限制（随 cny-footer 原样继承）：
 * - 订阅后缀 `(sub)` 仅对 `kimi-coding` 可判定，其余 provider 因扩展 API
 *   无 `modelRuntime.isUsingSubscription`（仅 internal，ModelRegistry 未暴露）
 *   而按 false 处理；
 * - `auto` 标记按原生默认值 `true` 硬编码，扩展 API 无 `autoCompactEnabled`
 *   开关；实验性 `xp` 角标未复刻。
 * - 路由显示从 entries 的最后一条 assistant message 推导（等价于原生的
 *   session.routedModel，即 latest response 的物理模型），无路由时不显示。
 */

import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

/**
 * USD → CNY 换算常数。这是写死的展示常数，不是实时汇率（无联网取数，也不自动更新），
 * 具体数值属于外部经验值、未用当前市场汇率核实；页脚金额只用于大致量级参考，
 * 精确对账请用账单。换价只改这里，无需动其他代码。
 */
export const USD_CNY = 7.1;

// ---- tokens/s：上一次 assistant generation 的最终速度（可单测） ----

export interface GenerationStatsInput {
  startedAt?: number;
  endedAt?: number;
  outputTokens?: number;
}

/**
 * tokens/s = output_tokens / generation_seconds。纯函数、无副作用。
 * output 必须 >0 且有限；duration 必须 >0。任一条件不满足返回 undefined
 *（调用方不显示速度，不伪造、不显示 0.0/NaN/Infinity）。input/cache/
 * reasoning 永不计入：reasoning 已包含在 output 内（Pi 官方定义）。
 */
export function calculateTokenSpeed(
  outputTokens: number | undefined,
  startedAt: number | undefined,
  endedAt: number | undefined,
): number | undefined {
  if (
    typeof outputTokens !== "number" ||
    !Number.isFinite(outputTokens) ||
    outputTokens <= 0
  )
    return undefined;
  if (typeof startedAt !== "number" || typeof endedAt !== "number") return undefined;
  const durationMs = endedAt - startedAt;
  if (!Number.isFinite(durationMs) || durationMs <= 0) return undefined;
  return outputTokens / (durationMs / 1000);
}

/** 有效速度 → `↯ 42.6/s`；无效输入返回空字符串（调用方跳过）。
 * 单位取裸 /s：行尾位置空间充足，符号后空格保证呼吸感；整行皆 token
 * 统计（↑↓R/W/CH），/s 无歧义，比 t/s 再省一列。 */
export function formatTokenSpeed(speed: number | undefined): string {
  if (typeof speed !== "number" || !Number.isFinite(speed) || speed <= 0) return "";
  return `↯ ${speed.toFixed(1)}/s`;
}

// ---- 纯函数：与原生 footer 实现一致（可单测） ----

export function formatFooterTokens(count: number): string {
  if (count < 1000) return count.toString();
  if (count < 1e4) return `${(count / 1000).toFixed(1)}k`;
  if (count < 1e6) return `${Math.round(count / 1000)}k`;
  if (count < 1e7) return `${(count / 1e6).toFixed(1)}M`;
  return `${Math.round(count / 1e6)}M`;
}

export function formatCwdForFooter(cwd: string, home: string | undefined): string {
  if (!home) return cwd;
  // Node path 语义：cwd 在 HOME 内则缩写为 ~，否则原样显示。
  // 为避免引入 node:path 依赖（保持零新增依赖），这里只做最常用的前缀匹配；
  // 边缘情况（大小写、符号链接、分隔符差异）回退为原样显示，不影响成本功能。
  const norm = (p: string) => p.replace(/\\/g, "/").replace(/\/+$/, "");
  const c = norm(cwd);
  const h = norm(home);
  if (c === h) return "~";
  if (c.startsWith(h + "/")) return "~" + cwd.slice(h.length);
  return cwd;
}

export function sanitizeStatusText(text: string): string {
  return text.replace(/[\r\n\t]/g, " ").replace(/ +/g, " ").trim();
}

/** USD 成本 → `¥x.xx` 显示字符串（含可选订阅后缀）。 */
export function formatCnyCost(usdCost: number, usingSubscription: boolean): string {
  const cny = usdCost * USD_CNY;
  return `¥${cny.toFixed(2)}${usingSubscription ? " (sub)" : ""}`;
}

export interface FooterUsageTotals {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  cost: number;
}

export interface UsageLike {
  input?: number;
  output?: number;
  cacheRead?: number;
  cacheWrite?: number;
  cost?: { total?: number };
}

export function emptyUsageTotals(): FooterUsageTotals {
  return { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0 };
}

export function addUsageToTotals(totals: FooterUsageTotals, usage: UsageLike | undefined | null): void {
  if (!usage) return;
  totals.input += usage.input ?? 0;
  totals.output += usage.output ?? 0;
  totals.cacheRead += usage.cacheRead ?? 0;
  totals.cacheWrite += usage.cacheWrite ?? 0;
  totals.cost += usage.cost?.total ?? 0;
}

// ---- 安装 / 卸载（公开 API，无 prototype patch） ----

// 跨实例单实例 guard：与两个 prototype adapter 的 Symbol.for 拒重同理。
// setFooter 本身是 last-writer-wins、无所有权校验；不用全局 guard 的话，
// 第二个实例的 install 会静默覆盖第一个实例的页脚，其 shutdown 还会把
// 仍活跃的属主页脚一起恢复成原生。/reload 场景由 shutdown 先清 guard，
// 故正常重载不受影响。
const FOOTER_OWNER_KEY = Symbol.for("pi.aiSummary.cnyFooter.v1");
type GlobalWithFooter = typeof globalThis & { [FOOTER_OWNER_KEY]?: true };

export function isCnyFooterInstalled(): boolean {
  return (globalThis as GlobalWithFooter)[FOOTER_OWNER_KEY] === true;
}

type SetFooterCtx = {
  mode?: unknown;
  model?: unknown;
  cwd?: string;
  ui?: { setFooter?: (factory: unknown) => void };
  sessionManager?: {
    getEntries?: () => Array<unknown>;
    getCwd?: () => string;
    getSessionName?: () => string;
  };
  getContextUsage?: () => unknown;
  thinkingLevel?: unknown;
};

/**
 * 接管页脚。成功返回 true；非 tui 模式、无 setFooter API、已全局安装、
 * 抛异常时返回 false。重复调用永不覆盖已生效的页脚。
 * getGeneration 可选：提供上一次 generation 计时（state.generation）时，
 * 页脚在左段末尾（context% 之后）追加 `↯ x.x/s`；缺省则保持原页脚不变。
 */
export function installCnyFooter(
  ctx: SetFooterCtx,
  getGeneration?: () => GenerationStatsInput | undefined,
): boolean {
  try {
    if (ctx.mode !== "tui") return false;
    const setFooter = ctx.ui?.setFooter;
    if (typeof setFooter !== "function") return false;
    if (isCnyFooterInstalled()) return false;
    const factory = (tui: any, theme: any, footerData: any) => {
      let unsub: (() => void) | undefined;
      try {
        unsub = footerData.onBranchChange(() => tui.requestRender());
      } catch {
        unsub = undefined;
      }
      return {
        dispose: unsub,
        invalidate() {},
        render(width: number): string[] {
          return renderCnyFooter(ctx, theme, footerData, width, getGeneration?.());
        },
      };
    };
    (setFooter as (f: unknown) => void).call(ctx.ui, factory);
    (globalThis as GlobalWithFooter)[FOOTER_OWNER_KEY] = true;
    return true;
  } catch {
    return false;
  }
}

/**
 * 恢复原生页脚。未安装时直接成功；成功恢复返回 true，抛异常返回 false
 *（保留全局属主，支持重试，与两个 prototype adapter 的冲突语义一致）。
 */
export function uninstallCnyFooter(ctx: SetFooterCtx): boolean {
  if (!isCnyFooterInstalled()) return true;
  try {
    const setFooter = ctx.ui?.setFooter;
    if (typeof setFooter !== "function") return false;
    (setFooter as (f: unknown) => void).call(ctx.ui, undefined);
    delete (globalThis as GlobalWithFooter)[FOOTER_OWNER_KEY];
    return true;
  } catch {
    return false;
  }
}

function renderCnyFooter(
  ctx: SetFooterCtx,
  theme: any,
  footerData: any,
  width: number,
  generation?: GenerationStatsInput,
): string[] {
  // 1. 全会话用量汇总（原生用 getEntries，不是 getBranch）。
  // 顺带记最后一条 assistant message 的 dispatch（provider/model/thinkingLevel），
  // 等价于原生的 session.routedModel（latest response 的物理模型）：同一循环内
  // 完成，不新增遍历。无 assistant message 时 routed 为空，不显示路由。
  const totals = emptyUsageTotals();
  let latestCacheHitRate: number | undefined;
  let routed: { model: string; thinkingLevel?: string } | undefined;
  let entries: Array<any> = [];
  try {
    entries = (ctx.sessionManager?.getEntries?.() as Array<any>) ?? [];
  } catch {
    entries = [];
  }
  for (const entry of entries) {
    const t = (entry as any)?.type;
    if (t === "usage") {
      addUsageToTotals(totals, (entry as any).usage);
    } else if (t === "message" && (entry as any).message?.role === "assistant") {
      const msg = (entry as any).message;
      addUsageToTotals(totals, msg.usage);
      if (typeof msg.model === "string" && msg.model) {
        routed = { model: msg.model };
        if (typeof msg.thinkingLevel === "string" && msg.thinkingLevel) {
          routed.thinkingLevel = msg.thinkingLevel;
        }
      }
      const u = msg.usage ?? {};
      const latestPromptTokens = (u.input ?? 0) + (u.cacheRead ?? 0) + (u.cacheWrite ?? 0);
      latestCacheHitRate = latestPromptTokens > 0 ? ((u.cacheRead ?? 0) / latestPromptTokens) * 100 : undefined;
    } else if (t === "message" && (entry as any).message?.role === "toolResult" && (entry as any).message?.usage) {
      addUsageToTotals(totals, (entry as any).message.usage);
    } else if ((t === "branch_summary" || t === "compaction") && (entry as any).usage) {
      addUsageToTotals(totals, (entry as any).usage);
    }
  }

  // 2. 上下文占用（原生：contextUsage?.percent / ?.contextWindow）。
  // 已知分歧行为：原生在 contextUsage undefined 时显示 "0.0"（原生
  // `contextUsage?.percent !== null` 对 undefined 为 true，疑似原生笔误）；
  // 本扩展按 "?" 显示，语义更准，无模型时不伪装出占比。
  let contextWindow = 0;
  let contextPercentValue = 0;
  let contextPercent: string = "?";
  try {
    const cu = ctx.getContextUsage?.() as any;
    contextWindow = cu?.contextWindow ?? (ctx.model as any)?.contextWindow ?? 0;
    if (typeof cu?.percent === "number") {
      contextPercentValue = cu.percent;
      contextPercent = cu.percent.toFixed(1);
    }
  } catch {
    contextWindow = (ctx.model as any)?.contextWindow ?? 0;
  }

  // 3. 第一行：pwd（cwd + git 分支 + session 名）。
  let pwd = "";
  try {
    const cwd = ctx.sessionManager?.getCwd?.() ?? ctx.cwd ?? "";
    pwd = formatCwdForFooter(cwd, process.env.HOME || (process as any).env?.USERPROFILE);
  } catch {
    pwd = ctx.cwd ?? "";
  }
  try {
    const branch = footerData.getGitBranch();
    if (branch) pwd = `${pwd} (${branch})`;
  } catch {
    /* 无 git 信息时保持 pwd 不变 */
  }
  try {
    const sessionName = (ctx.sessionManager as any)?.getSessionName?.();
    if (sessionName) pwd = `${pwd} • ${sessionName}`;
  } catch {
    /* 无 session 名时跳过 */
  }

  // 4. 第二行左半：token 统计。顺序与原生完全一致。
  const statsParts: string[] = [];
  if (totals.input) statsParts.push(`↑${formatFooterTokens(totals.input)}`);
  if (totals.output) statsParts.push(`↓${formatFooterTokens(totals.output)}`);
  if (totals.cacheRead) statsParts.push(`R${formatFooterTokens(totals.cacheRead)}`);
  if (totals.cacheWrite) statsParts.push(`W${formatFooterTokens(totals.cacheWrite)}`);
  if ((totals.cacheRead > 0 || totals.cacheWrite > 0) && latestCacheHitRate !== undefined) {
    statsParts.push(`CH${latestCacheHitRate.toFixed(1)}%`);
  }

  // 5. 唯一改动点：原生 `costStr = "$" + cost.toFixed(3)`，这里换算成人民币。
  // 原生订阅判断需要内部 modelRuntime，扩展 API 拿不到；仅保留可判定的
  // kimi-coding 分支，其余按 false 处理。
  const model = ctx.model as any;
  const usingSubscription = model ? model.provider === "kimi-coding" : false;
  if (totals.cost || usingSubscription) {
    statsParts.push(formatCnyCost(totals.cost, usingSubscription));
  }

  // auto 标记：原生默认 autoCompactEnabled = true；扩展 API 无此开关，按默认 true 处理。
  const autoIndicator = " (auto)";
  const contextPercentDisplay =
    contextPercent === "?" ? `?/${formatFooterTokens(contextWindow)}${autoIndicator}` : `${contextPercent}%/${formatFooterTokens(contextWindow)}${autoIndicator}`;
  let contextPercentStr: string;
  if (contextPercentValue > 90) {
    contextPercentStr = theme.fg("error", contextPercentDisplay);
  } else if (contextPercentValue > 70) {
    contextPercentStr = theme.fg("warning", contextPercentDisplay);
  } else {
    contextPercentStr = contextPercentDisplay;
  }
  statsParts.push(contextPercentStr);
  // 上一次 generation 的最终速度（本轮 message_start→message_end 窗口，
  // 不含 tool execution）。无可靠数据时跳过，不伪造。格式 `↯ x.x/s`。
  // 位置固定在左段末尾（context% 之后）：速度自身数值跳动只吞掉与右侧
  // 模型名之间的 padding，不再顶着前面的 ↑↓R¥ 等走，体感更稳定。
  if (generation) {
    const speedStr = formatTokenSpeed(
      calculateTokenSpeed(generation.outputTokens, generation.startedAt, generation.endedAt),
    );
    if (speedStr) statsParts.push(speedStr);
  }

  let statsLeft = statsParts.join(" ");
  const modelName = model?.id || "no-model";
  let statsLeftWidth = visibleWidth(statsLeft);
  if (statsLeftWidth > width) {
    statsLeft = truncateToWidth(statsLeft, width, "...");
    statsLeftWidth = visibleWidth(statsLeft);
  }

  // 6. 第二行右半：模型与 thinking level（与原生同逻辑）。
  // 虚拟模型路由：原生显示 `auto • high → gpt-5.6 • medium`（session.routedModel）。
  // 扩展拿不到 session 对象，用最后一条 assistant message 的 dispatch 推导：
  // 仅当路由模型与当前选择不同时追加 `→ {model}[ • {level}]`，无路由/一致时
  // 与原生（routed 为空）同样不显示。level 缺失时只显示模型（原生同逻辑）。
  const minPadding = 2;
  let rightSideWithoutProvider = modelName;
  if (model?.reasoning) {
    const thinkingLevel = (ctx as any).thinkingLevel || "off";
    rightSideWithoutProvider =
      thinkingLevel === "off" ? `${modelName} • thinking off` : `${modelName} • ${thinkingLevel}`;
  }
  if (routed && routed.model !== modelName) {
    const level = routed.thinkingLevel ? ` • ${routed.thinkingLevel}` : "";
    rightSideWithoutProvider += ` → ${routed.model}${level}`;
  }
  let rightSide = rightSideWithoutProvider;
  let providerCount = 1;
  try {
    providerCount = footerData.getAvailableProviderCount();
  } catch {
    providerCount = 1;
  }
  if (providerCount > 1 && model) {
    rightSide = `(${model.provider}) ${rightSideWithoutProvider}`;
    if (statsLeftWidth + minPadding + visibleWidth(rightSide) > width) {
      rightSide = rightSideWithoutProvider;
    }
  }

  const rightSideWidth = visibleWidth(rightSide);
  const totalNeeded = statsLeftWidth + minPadding + rightSideWidth;
  let statsLine: string;
  if (totalNeeded <= width) {
    const padding = " ".repeat(width - statsLeftWidth - rightSideWidth);
    statsLine = statsLeft + padding + rightSide;
  } else {
    const availableForRight = width - statsLeftWidth - minPadding;
    if (availableForRight > 0) {
      const truncatedRight = truncateToWidth(rightSide, availableForRight, "");
      const truncatedRightWidth = visibleWidth(truncatedRight);
      const padding = " ".repeat(Math.max(0, width - statsLeftWidth - truncatedRightWidth));
      statsLine = statsLeft + padding + truncatedRight;
    } else {
      statsLine = statsLeft;
    }
  }

  const dimStatsLeft = theme.fg("dim", statsLeft);
  const remainder = statsLine.slice(statsLeft.length);
  const dimRemainder = theme.fg("dim", remainder);
  const pwdLine = truncateToWidth(theme.fg("dim", pwd), width, theme.fg("dim", "..."));
  const lines = [pwdLine, dimStatsLeft + dimRemainder];
  try {
    const extensionStatuses = footerData.getExtensionStatuses();
    if (extensionStatuses.size > 0) {
      const statusEntries = Array.from(extensionStatuses.entries()) as Array<[string, string]>;
      const sortedStatuses = statusEntries
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([, text]) => sanitizeStatusText(text));
      const statusLine = sortedStatuses.join(" ");
      lines.push(truncateToWidth(statusLine, width, theme.fg("dim", "...")));
    }
  } catch {
    /* 无扩展状态时跳过第三行 */
  }
  return lines;
}

