// Pure collapsed-row builders. No Pi imports: theme access is injected as a
// ThemeLike, rows enter as plain snapshots. Errors thrown here are caught by
// the adapters, which fall back to Pi's native render.

import { firstVisibleLine, sanitizeInline, truncatePlain, visibleWidth } from "./ansi.ts";
import {
  formatDuration,
  formatToolError,
  formatToolOutcome,
  formatToolTarget,
  hasImageResult,
  type ToolArgsLike,
  type ToolResultLike,
} from "./format.ts";
import { safeFg, type ThemeLike } from "./theme.ts";

export type ToolStatus = "running" | "success" | "error";

export type ToolSnapshot = {
  toolName?: string;
  args: ToolArgsLike;
  status: ToolStatus;
  durationMs?: number;
  result?: ToolResultLike;
};

type Segment = { text: string; color?: string; flexible?: boolean; locked?: boolean };

const SEP = " · ";

// Collapsed rows sit 2 columns deep so they read as a layer distinct from
// flush-left prose (markers' OUTER_INSET = 2 is the same call). Narrow
// terminals drop the inset instead of squeezing the summary. Expanded rows
// keep native rendering untouched — Ctrl+O means "back to native".
const ROW_INSET = 2;
const MIN_INSET_WIDTH = 10;
// Continuation indent for the error line (beyond ROW_INSET): `    <error>`.
const ERROR_CONTINUATION_EXTRA = 2;
// Leading marker of the error continuation line: `    · <error>`.
const ERROR_MARKER = "· ";

// Fixed-column cap for the variable middle fragment (target / first error
// line), so rows stay scannable on wide terminals; duration/stats tails are
// unaffected. Terminal width remains the final guard (cap shrinks on narrow
// terminals via the flexible-fragment budget).
export const TOOL_TARGET_MAX_COLS = 60;

// Total-row budget for failed rows: each line caps at this on wide terminals;
// narrow terminals degrade to terminal width.
export const MAX_ROW_COLS = 100;
// Below this the error fragment is dropped entirely (✗ + red still marks
// the failure; markers' "tail disappears rather than spill" principle).
const MIN_ERROR_COLS = 10;

const STATUS_GLYPH: Record<ToolStatus, string> = {
  running: "·",
  success: "✓",
  error: "✗",
};

const STATUS_COLOR: Record<ToolStatus, string> = {
  running: "warning",
  success: "success",
  error: "error",
};

// Image results collapse to a marker only; the native renderer shows the
// image in expanded mode (v1 keeps every tool to one line while collapsed).
function outcomeFor(snapshot: ToolSnapshot): string | undefined {
  if (snapshot.status === "error") {
    return formatToolError(snapshot.result);
  }
  if (hasImageResult(snapshot.result)) return "image available";
  return formatToolOutcome(snapshot.toolName, snapshot.result);
}

// One-line target summary: path / command / pattern, per tool. Already
// sanitized (ANSI/control sequences stripped before any width math).
function targetFor(snapshot: ToolSnapshot): string | undefined {
  const target = formatToolTarget(snapshot.toolName, snapshot.args);
  return target === undefined
    ? undefined
    : truncatePlain(sanitizeInline(target), TOOL_TARGET_MAX_COLS);
}

// Assemble one single-line row. Overflow policy: the flexible target
// fragment is truncated first; failing that, trailing fragments are dropped
// (the locked tool-name fragment is never dropped); last resort truncates
// the last remaining fragment (the name). Everything fits `width` columns.
export function renderSegments(parts: Segment[], theme: ThemeLike | undefined, width: number): string {
  const max = Math.max(1, Math.floor(width));
  let parts_ = parts.filter((part) => part.text.length > 0);
  let total = parts_.reduce((sum, part) => sum + visibleWidth(part.text), 0);

  const flexIndex = parts_.findIndex((part) => part.flexible);
  if (total > max && flexIndex >= 0) {
    const budget = max - (total - visibleWidth(parts_[flexIndex]!.text));
    if (budget > 0) {
      parts_[flexIndex] = { ...parts_[flexIndex]!, text: truncatePlain(parts_[flexIndex]!.text, budget) };
    } else {
      parts_ = parts_.filter((_, index) => index !== flexIndex);
    }
    total = parts_.reduce((sum, part) => sum + visibleWidth(part.text), 0);
  }
  while (total > max && parts_.length > 1) {
    // Drop the last droppable fragment; locked fragments (tool name) are
    // never dropped wholesale — they get truncated by the final fallback.
    let drop = -1;
    for (let i = parts_.length - 1; i >= 1; i--) {
      if (!parts_[i]!.locked) {
        drop = i;
        break;
      }
    }
    if (drop === -1) break;
    total -= visibleWidth(parts_[drop]!.text);
    parts_.splice(drop, 1);
  }
  if (total > max && parts_.length > 1) {
    // Last resort: truncate the last remaining fragment (the name).
    const lastIdx = parts_.length - 1;
    const last = parts_[lastIdx]!;
    const budget = Math.max(0, max - (total - visibleWidth(last.text)));
    parts_[lastIdx] = { ...last, text: truncatePlain(last.text, budget) };
  }

  let line = "";
  for (const part of parts_) {
    line += part.color === undefined ? part.text : safeFg(theme, part.color, part.text);
  }
  return line;
}

// Failed row (two lines):
//   `  ✗ <name> <target> · <duration>`
//   `    · <error line>`
// Line 1 carries identity + timing; the error fragment lives on its own
// continuation line (inset + 2) with a leading `· ` marker, so long targets
// no longer squeeze the error out. `duration` sits on line 1 and survives
// independently of the error fragment. When there is no error text, or the
// continuation budget cannot fit the marker plus MIN_ERROR_COLS, the row
// degrades to a single line. All fragments are plain (already sanitized),
// tinted once in error color after the shared inset.
function buildErrorRow(
  name: string,
  target: string | undefined,
  duration: string,
  errorLine: string,
  inset: number,
  max: number,
): string[] {
  const totalBudget = Math.min(max, MAX_ROW_COLS);
  const lineBudget = Math.max(0, totalBudget - inset);
  // Continuation line gets its own budget; the leading marker lives on the
  // second line, so too narrow → single-line fallback.
  const secondBudget = Math.max(0, totalBudget - inset - ERROR_CONTINUATION_EXTRA);
  const errorBudget = Math.max(0, secondBudget - visibleWidth(ERROR_MARKER));
  const willShowError = errorLine.length > 0 && errorBudget >= MIN_ERROR_COLS;
  // The name can never push the row past the budget (long MCP tool names):
  // cap it first, then clamp the whole row as a final guard.
  const nameBudget = Math.max(0, totalBudget - inset - 2); // glyph + space
  const cappedName = truncatePlain(name, nameBudget);
  let remaining = totalBudget - inset - 2 - visibleWidth(cappedName);

  let first = `${STATUS_GLYPH.error} ${cappedName}`;
  // Reserve the duration tail before capping the target so it is not
  // silently truncated away by a long target.
  const durationCost = duration ? visibleWidth(SEP) + visibleWidth(duration) : 0;
  if (target && remaining > 1) {
    const targetBudget = Math.min(TOOL_TARGET_MAX_COLS, remaining - 1 - durationCost);
    if (targetBudget > 0) {
      const capped = truncatePlain(target, targetBudget);
      if (capped) {
        first += ` ${capped}`;
        remaining -= 1 + visibleWidth(capped);
      }
    }
  }

  if (duration) first += `${SEP}${duration}`;
  if (!willShowError) {
    return [truncatePlain(first, lineBudget)]; // plain, no inset — caller indents and tints
  }
  const second = `${ERROR_MARKER}${truncatePlain(errorLine, errorBudget)}`;
  return [truncatePlain(first, lineBudget), second]; // plain, no inset — caller indents and tints
}

// Collapsed tool row: `  ✓ read src/parser.ts · 0.4s · 312 lines` (2-col
// inset). Failed rows render entirely in error color. Single line, no
// leading blank: the inset plus the status glyph already separate rows from
// flush-left text (v0.1.x dropped the native leading Spacer for compactness).
export function buildCollapsedToolLines(
  snapshot: ToolSnapshot,
  theme: ThemeLike | undefined,
  width: number,
): string[] {
  const max = Math.max(1, Math.floor(width));
  const inset = max >= MIN_INSET_WIDTH ? ROW_INSET : 0;
  const contentWidth = max - inset;

  const name = sanitizeInline(snapshot.toolName ?? "tool");
  const target = targetFor(snapshot);
  const duration =
    snapshot.durationMs !== undefined ? formatDuration(snapshot.durationMs) : "";
  const outcome = outcomeFor(snapshot);

  if (snapshot.status === "error") {
    // Whole row in error color; the error fragment continues on its own
    // line. Base inset stays outside the color; the continuation line adds
    // ERROR_CONTINUATION_EXTRA on top.
    const rows = buildErrorRow(name, target, duration, outcome ?? "", inset, max);
    return rows.map((row, index) =>
      " ".repeat(inset + (index > 0 ? ERROR_CONTINUATION_EXTRA : 0)) +
      safeFg(theme, "error", row),
    );
  }

  const outcomeCap = Math.min(TOOL_TARGET_MAX_COLS, contentWidth);
  const cappedOutcome =
    outcome === undefined ? undefined : truncatePlain(outcome, outcomeCap);

  // Fragments before the flexible target.
  const head: Segment[] = [
    { text: STATUS_GLYPH[snapshot.status], color: STATUS_COLOR[snapshot.status] },
    { text: " " },
    // Locked: the name is dropped-never, truncated-last (renderSegments tail
    // policy). Marking it here avoids an index-coupled post-assignment.
    { text: name, color: "toolTitle", locked: true },
  ];
  const tail: Segment[] = [];
  if (duration) tail.push({ text: SEP, color: "dim" }, { text: duration, color: "dim" });
  if (cappedOutcome) {
    tail.push({ text: SEP, color: "dim" }, { text: cappedOutcome, color: "dim" });
  }

  const parts: Segment[] = target
    ? [...head, { text: " " }, { text: target, color: "toolOutput", flexible: true }, ...tail]
    : [...head, ...tail];

  return [" ".repeat(inset) + renderSegments(parts, theme, contentWidth)];
}

// ---------- thinking ----------

export type ThinkingContentLike = { type: "thinking"; thinking: string };

// Merge adjacent thinking blocks into a display-only copy. Blocks separated
// by visible text (or message boundaries) stay separate. Provider fields
// (signatures, redacted blocks) are preserved untouched — the session
// message is never modified.
export function combineAdjacentThinking(content: readonly unknown[]): unknown[] | undefined {
  if (!Array.isArray(content)) return undefined;
  const hasAdjacent =
    content.some(isThinkingBlock) &&
    content.some(
      (block, index) => isThinkingBlock(block) && isThinkingBlock(content[index + 1]),
    );
  if (!hasAdjacent) return undefined;

  const merged: unknown[] = [];
  for (const block of content) {
    const previous = merged.at(-1);
    if (isThinkingBlock(previous) && isThinkingBlock(block)) {
      merged[merged.length - 1] = {
        ...previous,
        thinking: `${previous.thinking.trim()}\n\n${block.thinking.trim()}`,
      };
      continue;
    }
    merged.push(block);
  }
  return merged;
}

function isThinkingBlock(block: unknown): block is ThinkingContentLike {
  return (
    !!block &&
    typeof block === "object" &&
    (block as { type?: unknown }).type === "thinking" &&
    typeof (block as { thinking?: unknown }).thinking === "string"
  );
}

// Consecutive non-empty thinking runs, merged per run. Used for the label
// preview and the token estimate.
export function thinkingRuns(content: readonly unknown[]): string[] {
  if (!Array.isArray(content)) return [];
  const runs: string[] = [];
  let current: string[] = [];
  for (const block of content) {
    if (isThinkingBlock(block)) {
      if (block.thinking.trim()) current.push(block.thinking);
      continue;
    }
    if (current.length > 0) runs.push(current.join("\n\n"));
    current = [];
  }
  if (current.length > 0) runs.push(current.join("\n\n"));
  return runs;
}

// Preview: first non-empty line of the (merged) thinking text, sanitized,
// truncated to visible width. No model re-summarization; original untouched.
export function thinkingPreview(text: string, maxWidth: number): string | undefined {
  const first = firstVisibleLine(text);
  if (first === undefined) return undefined;
  return truncatePlain(first, Math.max(1, maxWidth));
}

export type ThinkingLabelInput = {
  preview?: string;
};

// Streaming and settled MUST build byte-identical labels (`+ Thought[: <preview>]`).
// The label is written before every original updateContent call; a change after
// settle rewrites a row that may already be above the viewport, and TuiMainScreen
// then calls fullRender(true) (clears scrollback + replays the whole session).
// Decision: drop the former settled-only ` · 12.3s · ≈1.8K tok` tail.
export function buildThinkingLabel(input: ThinkingLabelInput): string {
  return input.preview ? `+ Thought: ${input.preview}` : "+ Thought";
}

extensions.pi-ai-summary/src/theme.ts:
// Theme access. v1 uses only Pi's existing theme tokens (no custom tokens).
// Every fg() call is guarded: an unknown token or changed theme API degrades
// to plain text instead of breaking the row (fallback discipline, §XI).

export type ThemeLike = {
  fg(color: string, text: string): string;
  bold?(text: string): string;
  getFgAnsi?(color: string): string;
  // Official Theme API (Theme.bg): full-row background tints. Optional so
  // older/fake themes degrade to the accent-bar marker form.
  bg?(color: string, text: string): string;
};

export function safeFg(
  theme: ThemeLike | undefined,
  color: string,
  text: string,
): string {
  if (!theme || text.length === 0) return text;
  try {
    return theme.fg(color, text);
  } catch {
    return text;
  }
}

// Background twin of safeFg. Failure → plain text (callers treat a missing
// bg as "marker unavailable" and fall back to the accent bar).
export function safeBg(
  theme: ThemeLike | undefined,
  color: string,
  text: string,
): string {
  if (!theme || typeof theme.bg !== "function" || text.length === 0) return text;
  try {
    return theme.bg(color, text);
  } catch {
    return text;
  }
}

// Sample of every token this extension renders with; used as a cheap theme
// identity for the settled-row cache (a theme switch swaps the object).
const SAMPLE_TOKENS = [
  "toolTitle",
  "muted",
  "toolOutput",
  "dim",
  "success",
  "warning",
  "error",
] as const;

export function themeSample(theme: ThemeLike | undefined): string {
  if (!theme) return "none";
  let sample = "";
  for (const token of SAMPLE_TOKENS) {
    try {
      sample += theme.fg(token, "x");
    } catch {
      sample += token;
    }
  }
  return sample;
}

