// ANSI/OSC/control-char sanitation and display-width utilities for
// single-line collapsed rows. Pure functions, no Pi imports — kept
// dependency-free so they are unit-testable outside the TUI.

// OSC first: a payload match must stop at the first BEL/ST terminator,
// because visible text sits BETWEEN two OSC sequences (e.g. Pi's
// `ESC]8;;url ESC\ <path> ESC]8;; ESC\` hyperlinks); a greedy match would
// swallow that path along with the sequences.
const OSC_RE = /\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g;
const CSI_RE = /\x1b\[[0-?]*[ -/]*[@-~]/g;
const TWO_BYTE_RE = /\x1b[@-Z\\-_]/g;
const C0_RE = /[\x00-\x1f\x7f]/g;

export function stripAnsi(text: string): string {
  return text.replace(OSC_RE, "").replace(CSI_RE, "").replace(TWO_BYTE_RE, "");
}

// Leading run of zero-width escape sequences (OSC/CSI/2-byte) at the start
// of a line. Used to insert markers after the prefix without breaking zone
// markers or counting escapes toward visible width.
const LEADING_ESC_RE =
  /^(?:\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\\-_])*/;

export function leadingEscapePrefix(line: string): string {
  return LEADING_ESC_RE.exec(line)?.[0] ?? "";
}

// Command output can carry cursor-moving control bytes, raw terminal
// sequences, line feeds, tabs and carriage returns. Collapsed rows are
// single-line, so everything is reduced to a clean single line of text.
export function sanitizeInline(text: string): string {
  return stripAnsi(text).replace(/\r/g, " ").replace(C0_RE, " ");
}

// First line that survives sanitation with visible content.
export function firstVisibleLine(text: unknown): string | undefined {
  if (typeof text !== "string") return undefined;
  for (const raw of text.split("\n")) {
    const line = sanitizeInline(raw).trim();
    if (line.length > 0) return line;
  }
  return undefined;
}

// East Asian Wide/Fullwidth ranges plus common emoji blocks. Conservative:
// ambiguous-width characters count as 1 column.
const WIDE_RANGES: ReadonlyArray<readonly [number, number]> = [
  [0x1100, 0x115f],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe30, 0xfe4f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f300, 0x1f64f],
  [0x1f900, 0x1f9ff],
  [0x20000, 0x2fffd],
  [0x30000, 0x3fffd],
];

function codePointWidth(cp: number): number {
  for (const [lo, hi] of WIDE_RANGES) {
    if (cp >= lo && cp <= hi) return 2;
  }
  return 1;
}

export function visibleWidth(text: string): number {
  let width = 0;
  for (const ch of stripAnsi(text)) {
    const cp = ch.codePointAt(0);
    if (cp === undefined) continue;
    width += codePointWidth(cp);
  }
  return width;
}

// Truncate a plain (already sanitized) string to fit maxWidth columns,
// appending an ellipsis when characters were dropped.
export function truncatePlain(text: string, maxWidth: number): string {
  if (maxWidth <= 0) return "";
  const chars = [...text];
  let width = 0;
  let cut = -1;
  for (let i = 0; i < chars.length; i++) {
    const w = codePointWidth(chars[i]!.codePointAt(0) ?? 0);
    if (width + w > maxWidth) {
      cut = i;
      break;
    }
    width += w;
  }
  if (cut === -1) return text;
  // Back off so the 1-column ellipsis still fits.
  while (width + 1 > maxWidth && cut > 0) {
    cut--;
    width -= codePointWidth(chars[cut]!.codePointAt(0) ?? 0);
  }
  const kept = chars.slice(0, cut).join("");
  return width + 1 <= maxWidth ? kept + "…" : kept;
}

extensions.pi-ai-summary/src/state.ts:
// Read-only event-side state. Nothing here is authoritative for rendering:
// per M-2, identity/args/result/status always come from component fields;
// the tools map carries timing captured from public events, with component
// `rendererState` as the fallback. Thinking duration is row-local (streaming
// flags in the adapter) — production streaming messages carry no `id` field
// (verified v0.1.5), so the former event-side thinking timing was dead code
// and was removed in v0.1.8.

export type ToolTiming = {
  toolName?: string;
  startedAt?: number;
  endedAt?: number;
};

// Last assistant generation timing for footer tokens/s display.
// - startedAt: Date.now() captured at `message_start` (assistant only).
// - endedAt/outputTokens: Date.now() + final `usage.output` captured at
//   `message_end` (assistant only). A new `message_start` resets the slot so
//   a stale end can never pair with a fresh start.
// Speed itself is derived at render time (see calculateTokenSpeed in
// footer-cny.ts); state stays raw data, no computed values.
export type GenerationStats = {
  startedAt?: number;
  endedAt?: number;
  outputTokens?: number;
};

export type SessionState = {
  // Keyed by toolCallId. Unsettled entries are dropped at agent_end;
  // settled timings survive across turns until session_shutdown.
  tools: Map<string, ToolTiming>;
  // Last assistant generation (message_start → message_end window).
  // Persists across turns until the next generation starts; cleared only
  // on session_shutdown. The footer shows the last completed generation's
  // speed, so a new turn without a new generation keeps the old value
  // (not a bug: there is simply no newer data).
  generation: GenerationStats;
  // Weak ref to the latest turn's final text answer message OBJECT
  // (accent bar target, display-only). Object identity is used because
  // streaming messages carry no stable id (verified: keys are role/content/
  // api/provider/model/usage/stopReason/timestamp/responseId). Event-side
  // only: unset after session restore until the next agent_end. WeakRef so
  // the answer content is not retained.
  finalAnswerRef?: WeakRef<object>;
};

export function createSessionState(): SessionState {
  return { tools: new Map(), generation: {} };
}

// agent_end: drop tools that never settled. Settled entries stay until
// session_shutdown — restored rows and late renders may still read them.
export function sealTurnState(state: SessionState): void {
  for (const [id, timing] of state.tools) {
    if (timing.endedAt === undefined) state.tools.delete(id);
    else if (timing.startedAt === undefined) timing.startedAt = Date.now();
  }
}

export function clearSessionState(state: SessionState): void {
  state.tools.clear();
  state.finalAnswerRef = undefined;
  state.generation = {};
}

extensions.pi-ai-summary/src/format.ts:
// Pure formatting helpers for collapsed tool rows. All readers are
// defensive: any missing/mistyped field yields `undefined` and the caller
// omits that fragment — nothing is fabricated (M-2).

import { firstVisibleLine } from "./ansi.ts";

export type ToolResultLike = {
  isError?: unknown;
  content?: Array<{ type?: unknown; text?: unknown }>;
  details?: Record<string, unknown> | undefined;
};

export type ToolArgsLike = Record<string, unknown> | undefined;

export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return "";
  return `${(ms / 1000).toFixed(1)}s`;
}

function firstText(result: ToolResultLike | undefined): string | undefined {
  const content = result?.content;
  if (!Array.isArray(content)) return undefined;
  for (const item of content) {
    if (item?.type === "text" && typeof item.text === "string") return item.text;
  }
  return undefined;
}

export function hasImageResult(result: ToolResultLike | undefined): boolean {
  const content = result?.content;
  return Array.isArray(content)
    ? content.some((item) => item?.type === "image")
    : false;
}

export function isResultError(result: ToolResultLike | undefined): boolean {
  return result?.isError === true;
}

function argString(args: ToolArgsLike, key: string): string | undefined {
  const value = args?.[key];
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function firstPathLikeArg(args: ToolArgsLike): string | undefined {
  return argString(args, "path") ?? argString(args, "file_path");
}

// Count `+`/`-` lines in a unified diff; read-only, never written back.
export function diffStats(diff: unknown): { plus: number; minus: number } | undefined {
  if (typeof diff !== "string" || diff.length === 0) return undefined;
  let plus = 0;
  let minus = 0;
  for (const line of diff.split("\n")) {
    if (line.startsWith("+") && !line.startsWith("+++")) plus++;
    else if (line.startsWith("-") && !line.startsWith("---")) minus++;
  }
  return { plus, minus };
}

function countOutputLines(result: ToolResultLike | undefined): number | undefined {
  const text = firstText(result);
  if (text === undefined) return undefined;
  return text.split("\n").filter((line) => line.trim().length > 0).length;
}

// One-line target summary: path / command / pattern, per tool.
export function formatToolTarget(
  toolName: string | undefined,
  args: ToolArgsLike,
): string | undefined {
  if (!toolName) return undefined;
  switch (toolName) {
    case "read":
    case "edit":
    case "write":
      return firstPathLikeArg(args);
    case "bash": {
      const command = argString(args, "command");
      return command === undefined ? undefined : command.replace(/\s+/g, " ").trim();
    }
    case "grep": {
      const pattern = argString(args, "pattern");
      if (pattern === undefined) return undefined;
      const path = argString(args, "path");
      return `"${pattern}"${path ? ` ${path}` : ""}`;
    }
    case "find": {
      const pattern = argString(args, "pattern") ?? argString(args, "glob");
      if (pattern === undefined) return undefined;
      const path = argString(args, "path");
      return `${pattern}${path ? ` ${path}` : ""}`;
    }
    case "ls":
      return firstPathLikeArg(args);
    default: {
      // Unknown/MCP tools: compact JSON of the args, squashed for one line.
      if (!args || typeof args !== "object") return undefined;
      try {
        const json = JSON.stringify(args);
        return json === "{}" ? undefined : json.replace(/\s+/g, " ");
      } catch {
        return undefined;
      }
    }
  }
}

// Outcome fragment: result statistics per tool. `undefined` → omit.
// Line-count口径：read/write 的 "N lines" 是文件原始行数（含空行，与文件
// 内容一致）；find/grep/ls 的 "N results" 是非空输出行数（结果行语义）。
// write 不再输出行数：pi 的 write 工具 result 是确认消息
// （"Successfully wrote to <path>"，已核实源码），不含写入内容。
export function formatToolOutcome(
  toolName: string | undefined,
  result: ToolResultLike | undefined,
): string | undefined {
  if (!result) return undefined;
  if (isResultError(result)) return undefined; // error line carries the message

  const details = result.details ?? undefined;
  const truncation =
    details?.truncation && typeof details.truncation === "object"
      ? (details.truncation as { truncated?: unknown; totalLines?: unknown })
      : undefined;

  switch (toolName) {
    case "read": {
      const text = firstText(result);
      const lines =
        typeof text === "string" ? text.split("\n").length : undefined;
      if (lines === undefined && !truncation?.truncated) return undefined;
      let out = lines !== undefined ? `${lines} lines` : "";
      if (truncation?.truncated) {
        out += `${out ? " · " : ""}truncated from ${typeof truncation.totalLines === "number" ? truncation.totalLines : "?"}`;
      }
      return out || undefined;
    }
    case "write":
      // result 是确认消息而非文件内容，行数统计无意义 → 省略。
      return undefined;
    case "edit": {
      const stats = diffStats(details?.diff);
      return stats ? `+${stats.plus}/-${stats.minus}` : undefined;
    }
    case "bash": {
      const exitCode = details?.exitCode;
      if (typeof exitCode === "number") {
        return exitCode === 0 ? "done" : `exit ${exitCode}`;
      }
      const text = firstText(result);
      const match =
        typeof text === "string" ? text.match(/exit code: (\d+)/) : null;
      return match ? (match[1] === "0" ? "done" : `exit ${match[1]}`) : undefined;
    }
    case "find":
    case "grep":
    case "ls": {
      const count = countOutputLines(result);
      return count !== undefined ? `${count} results` : undefined;
    }
    default:
      return undefined;
  }
}

// First error line, sanitized; `undefined` → caller omits the fragment.
export function formatToolError(result: ToolResultLike | undefined): string | undefined {
  if (!result) return undefined;
  const text = firstText(result);
  return text === undefined ? undefined : (firstVisibleLine(text) ?? undefined);
}

