// Public-event collection. Payload field names follow the official
// ExtensionAPI docs; PI_AI_SUMMARY_DIAG=1 enables a redacted payload dump
// (types, field names, lengths — never content) for runtime confirmation.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { appendFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import {
  clearSessionState,
  sealTurnState,
  type SessionState,
} from "./state.ts";

const DIAG_ENV = "PI_AI_SUMMARY_DIAG";
const DIAG_PATH = join(tmpdir(), "pi-ai-summary-diag.log");

// Redacted diagnostics: shapes only — event type, block types, text
// lengths, field names. Never thinking text, args, results or file content.
export function diagEnabled(): boolean {
  const value = process.env[DIAG_ENV]?.trim().toLowerCase();
  return value === "1" || value === "true" || value === "yes" || value === "on";
}

export function diag(event: string, fields: Record<string, unknown>): void {
  try {
    const line = `${new Date().toISOString()} ${event} ${JSON.stringify(fields)}\n`;
    appendFileSync(DIAG_PATH, line);
  } catch {
    // Diagnostics must never break the session.
  }
}

// A render fallback is only UNEXPECTED when a row that should be collapsible
// (or decoratable) fails to build — guards like expanded/visible mode are
// designed pass-throughs and never reach this counter. Persistent streaks
// mean the extension is silently dead, worth one log line per session even
// without PI_AI_SUMMARY_DIAG.
export const FALLBACK_ALERT_AFTER = 20;

export type FallbackTracker = { n: number; alerted: boolean };

export function newFallbackTracker(): FallbackTracker {
  return { n: 0, alerted: false };
}

export function noteRenderFallback(
  tracker: FallbackTracker,
  source: string,
  detail: string,
): void {
  tracker.n++;
  if (tracker.alerted || tracker.n < FALLBACK_ALERT_AFTER) return;
  tracker.alerted = true;
  // One-shot: independent of the PI_AI_SUMMARY_DIAG gate.
  diag("degraded_render", { source, detail, consecutive: tracker.n });
}

export function resetRenderFallback(tracker: FallbackTracker): void {
  tracker.n = 0;
}

export { DIAG_PATH };

function blockShapes(message: unknown): unknown {
  const content = (message as { content?: unknown })?.content;
  if (!Array.isArray(content)) return { content: "absent" };
  return content.map((block) => {
    const type = (block as { type?: unknown })?.type;
    const text =
      typeof (block as { text?: unknown })?.text === "string"
        ? (block as { text: string }).text.length
        : undefined;
    const thinking =
      typeof (block as { thinking?: unknown })?.thinking === "string"
        ? (block as { thinking: string }).thinking.length
        : undefined;
    return { type, textLength: text, thinkingLength: thinking };
  });
}

function usageFieldNames(message: unknown): unknown {
  const usage = (message as { usage?: unknown })?.usage;
  return usage && typeof usage === "object" ? Object.keys(usage) : undefined;
}

function hasTextContent(content: unknown): boolean {
  return (
    Array.isArray(content) &&
    content.some(
      (block) =>
        (block as { type?: unknown })?.type === "text" &&
        typeof (block as { text?: unknown }).text === "string" &&
        (block as { text: string }).text.trim().length > 0,
    )
  );
}

export function registerEventHandlers(pi: ExtensionAPI, state: SessionState): void {
  const diagOn = diagEnabled();
  // Latest assistant message with non-empty text since the last agent_end;
  // promoted to state.finalAnswerRef at turn end (accent bar target).
  // Object identity, not id: streaming messages carry no id (verified).
  let turnLastText: object | undefined;

  pi.on("tool_execution_start", (event) => {
    state.tools.set(event.toolCallId, {
      toolName: event.toolName,
      startedAt: Date.now(),
    });
    if (diagOn) {
      diag("tool_execution_start", {
        toolCallId: event.toolCallId,
        toolName: event.toolName,
        argKeys:
          event.args && typeof event.args === "object"
            ? Object.keys(event.args as Record<string, unknown>)
            : undefined,
      });
    }
  });

  pi.on("tool_execution_update", (event) => {
    // partialResult is a cumulative snapshot, not a delta. v1 replaces
    // nothing and shows no intermediate body in the collapsed row; timing
    // stays anchored to start/end.
    if (diagOn) {
      diag("tool_execution_update", {
        toolCallId: event.toolCallId,
        toolName: event.toolName,
        hasPartialResult: event.partialResult !== undefined,
        partialResultFieldNames:
          event.partialResult && typeof event.partialResult === "object"
            ? Object.keys(event.partialResult as Record<string, unknown>)
            : undefined,
      });
    }
  });

  pi.on("tool_execution_end", (event) => {
    const timing = state.tools.get(event.toolCallId);
    if (timing) timing.endedAt = Date.now();
    if (diagOn) {
      diag("tool_execution_end", {
        toolCallId: event.toolCallId,
        toolName: event.toolName,
        isError: event.isError,
        resultFieldNames:
          event.result && typeof event.result === "object"
            ? Object.keys(event.result as Record<string, unknown>)
            : undefined,
      });
    }
  });

  pi.on("message_start", (event) => {
    // Generation window opens when the provider stream starts. Assistant
    // only: user/toolResult/system messages also emit message_start.
    // Resets the slot so a stale end can never pair with a fresh start.
    const message = event.message as { role?: unknown } | undefined;
    if (message?.role !== "assistant") return;
    state.generation = { startedAt: Date.now() };
    if (diagOn) diag("message_start", { role: message.role });
  });

  pi.on("message_update", (event) => {
    // The event message is a cumulative snapshot, never a delta. Thinking
    // timing is row-local (adapter-side); this event is diagnostics-only.
    if (diagOn) {
      const message = event.message as
        | { id?: unknown; role?: unknown; content?: unknown; usage?: unknown }
        | undefined;
      const streamEvent = (
        event as { assistantMessageEvent?: { type?: unknown } }
      ).assistantMessageEvent;
      diag("message_update", {
        role: message?.role,
        messageId: typeof message?.id === "string" ? message.id : undefined,
        blocks: blockShapes(message),
        assistantMessageEventType: streamEvent?.type,
        usageFieldNames: usageFieldNames(message),
      });
    }
  });

  pi.on("message_end", (event) => {
    const message = event.message as
      | { id?: unknown; role?: unknown; content?: unknown; usage?: unknown }
      | undefined;
    if (message?.role !== "assistant") return;
    // Generation window closes with the final message carrying final usage.
    // Streaming message_update usage is partial/unreliable, so only the
    // message_end snapshot is used. usage.output already includes reasoning
    // tokens (Pi defines reasoning as a subset of output) — never added.
    const output = (message.usage as { output?: unknown } | undefined)?.output;
    state.generation.endedAt = Date.now();
    state.generation.outputTokens =
      typeof output === "number" && Number.isFinite(output) && output > 0
        ? output
        : undefined;
    // Accent-bar candidate: last assistant message with visible text this
    // turn. The object identity matches what the TUI passes to
    // updateContent (same event object, no cloning).
    if (hasTextContent(message.content)) turnLastText = message;
    if (diagOn) {
      diag("message_end", {
        role: message.role,
        blocks: blockShapes(message),
        usageFieldNames: usageFieldNames(message),
      });
    }
  });

  pi.on("agent_end", () => {
    // Seal the turn's thinking, drop never-settled tools. No divider, no
    // custom session message, no cleanup of settled render data.
    sealTurnState(state);
    // Promote this turn's final text answer (if any) to the accent-bar
    // target; a turn without prose keeps the previous answer marked.
    if (turnLastText !== undefined) {
      state.finalAnswerRef = new WeakRef(turnLastText);
      turnLastText = undefined;
    }
    if (diagOn) diag("agent_end", {});
  });

  pi.on("session_shutdown", () => {
    clearSessionState(state);
  });
}

extensions.pi-ai-summary/src/adapters/tool-render.t:
// Adapter 1: ToolExecutionComponent.prototype.render (+ updateDisplay for
// cache invalidation).
//
// RED LINES (§XI / README):
// - collapsed → one-line summary; expanded → the ORIGINAL render(), so
//   Ctrl+O always restores Pi's full native output;
// - never re-registers built-in tools, never touches args/results/execution;
// - feature-detect → Symbol.for single-instance guard → restore on
//   session_shutdown → any failure falls back to the original method;
// - no timers: running rows refresh their elapsed time only when Pi
//   re-renders for other reasons.

import { ToolExecutionComponent } from "@earendil-works/pi-coding-agent";
import { isResultError, type ToolResultLike } from "../format.ts";
import type { SessionState } from "../state.ts";
import {
  newFallbackTracker,
  noteRenderFallback,
  resetRenderFallback,
  type FallbackTracker,
} from "../events.ts";
import {
  buildCollapsedToolLines,
  type ToolSnapshot,
} from "../summaries.ts";
import { themeSample, type ThemeLike } from "../theme.ts";

const PATCH_KEY = Symbol.for("pi.aiSummary.toolRender.v1");

type ToolExecutionRow = {
  toolName?: unknown;
  toolCallId?: unknown;
  args?: unknown;
  expanded?: unknown;
  isPartial?: unknown;
  hideComponent?: unknown;
  result?: ToolResultLike;
  rendererState?: { startedAt?: unknown; endedAt?: unknown };
};

type PatchState = {
  originalRender: (width: number) => string[];
  originalUpdateDisplay: () => void;
  patchedRender?: (width: number) => string[];
  patchedUpdateDisplay?: () => void;
  getTheme: () => ThemeLike | undefined;
  timings: SessionState;
  // Consecutive unexpected build failures → one-shot diag alert.
  degradation: FallbackTracker;
  cache: WeakMap<object, { width: number; signature: string; version: number; theme: string; lines: string[] }>;
  versions: WeakMap<object, number>;
};

type ProtoWithPatch = ToolExecutionRow & {
  [PATCH_KEY]?: PatchState;
  render?: (width: number) => string[];
  updateDisplay?: () => void;
};

// Redacted row-shape snapshot for the degradation alert (types/lengths only,
// never content) — enough to identify which component keeps failing builds.
// Must never throw: rows can carry poisoned getters (see the fallback test).
function rowShape(row: ToolExecutionRow): Record<string, unknown> {
  try {
    return {
      toolNameType: typeof row.toolName,
      toolNameLen: typeof row.toolName === "string" ? row.toolName.length : undefined,
      hasToolCallId: typeof row.toolCallId === "string",
      expandedType: typeof row.expanded,
      isPartial: row.isPartial,
      hasResult: row.result !== undefined,
      argsType: typeof row.args,
    };
  } catch {
    return { shapeError: true };
  }
}

function rowSignature(row: ToolExecutionRow): string {
  return `${row.isPartial === false ? 0 : 1}|${row.expanded === true ? 1 : 0}|${row.result ? 1 : 0}|${isResultError(row.result) ? 1 : 0}`;
}

function resultShapeOk(result: unknown): result is ToolResultLike {
  return result === undefined || result === null || typeof result === "object";
}

// M-2: identity/args/result/status always come from the component fields
// (freshest at render time); timing prefers event state and falls back to
// the component's rendererState. Missing sources → fragment omitted.
function snapshotFromRow(row: ToolExecutionRow, state: PatchState): ToolSnapshot | undefined {
  if (typeof row.toolName !== "string" || row.toolName.length === 0) return undefined;
  if (!resultShapeOk(row.result)) return undefined;

  const settled = row.isPartial === false;
  const status = !settled
    ? ("running" as const)
    : isResultError(row.result)
      ? ("error" as const)
      : ("success" as const);

  let startedAt: number | undefined;
  let endedAt: number | undefined;
  if (typeof row.toolCallId === "string") {
    const timing = state.timings.tools.get(row.toolCallId);
    if (timing) {
      startedAt = timing.startedAt;
      endedAt = timing.endedAt;
    }
  }
  if (startedAt === undefined && typeof row.rendererState?.startedAt === "number") {
    startedAt = row.rendererState.startedAt;
  }
  if (endedAt === undefined && typeof row.rendererState?.endedAt === "number") {
    endedAt = row.rendererState.endedAt;
  }

  let durationMs: number | undefined;
  if (typeof startedAt === "number" && Number.isFinite(startedAt)) {
    const end = settled && typeof endedAt === "number" ? endedAt : Date.now();
    if (end >= startedAt) durationMs = end - startedAt;
  }

  return {
    toolName: row.toolName,
    args: (row.args ?? undefined) as ToolSnapshot["args"],
    status,
    durationMs,
    result: row.result,
  };
}

function install(
  getTheme: () => ThemeLike | undefined,
  timings: SessionState,
): PatchState | undefined {
  try {
    const proto = ToolExecutionComponent?.prototype as unknown as ProtoWithPatch | undefined;
    if (!proto || typeof proto.render !== "function" || typeof proto.updateDisplay !== "function") {
      return undefined;
    }
    // One active installation per prototype; never borrow another
    // instance's callbacks/state. The caller reports installation failure.
    if (proto[PATCH_KEY]) return undefined;

    const state: PatchState = {
      originalRender: proto.render,
      originalUpdateDisplay: proto.updateDisplay,
      getTheme,
      timings,
      degradation: newFallbackTracker(),
      cache: new WeakMap(),
      versions: new WeakMap(),
    };

    const patchedUpdateDisplay = function updateDisplayWithCacheBump(this: ToolExecutionRow): void {
      // A real display update can change args/results without changing the
      // shape signature; bump the version so cached lines rebuild.
      state.versions.set(this, (state.versions.get(this) ?? 0) + 1);
      state.cache.delete(this);
      state.originalUpdateDisplay.call(this);
    };

    const patchedRender = function renderWithCollapsedRow(
      this: ToolExecutionRow,
      width: number,
    ): string[] {
      // Full-body guard: row fields (expanded/isPartial/result getters) and
      // state reads sit outside the per-branch builder guard; a poisoned
      // getter must degrade to Pi's native rendering instead of letting the
      // exception reach the TUI render tick (pi exits on uncaughtException).
      try {
        return renderCollapsedRow.call(this, width);
      } catch {
        noteRenderFallback(state.degradation, "tool_render", JSON.stringify({ ...rowShape(this), threw: true }));
        return state.originalRender.call(this, width);
      }
    };

    function renderCollapsedRow(
      this: ToolExecutionRow,
      width: number,
    ): string[] {
      const theme = state.getTheme();
      // Guards: unrecognized shapes, hidden rows, and expanded rows all keep
      // Pi's native rendering verbatim.
      if (
        !theme ||
        typeof this.expanded !== "boolean" ||
        this.expanded ||
        this.hideComponent === true
      ) {
        return state.originalRender.call(this, width);
      }

      const settled = this.isPartial === false;
      if (settled) {
        // Settled-row render cache. Pi re-renders the transcript on every
        // keystroke; settled collapsed rows are static between display
        // updates. Running/partial rows are never cached.
        const signature = rowSignature(rowFrom(this, state));
        const version = state.versions.get(this) ?? 0;
        const sample = themeSample(theme);
        const cached = state.cache.get(this);
        if (
          cached &&
          cached.width === width &&
          cached.signature === signature &&
          cached.version === version &&
          cached.theme === sample
        ) {
          return cached.lines;
        }
        const lines = buildFromRow(this, state, theme, width);
        if (lines) {
          state.cache.set(this, { width, signature, version, theme: sample, lines });
          resetRenderFallback(state.degradation);
          return lines;
        }
        noteRenderFallback(state.degradation, "tool_render", JSON.stringify(rowShape(this)));
        return state.originalRender.call(this, width);
      }

      // Running rows: rebuilt per render (dynamic elapsed time), no timer.
      const lines = buildFromRow(this, state, theme, width);
      if (lines) {
        resetRenderFallback(state.degradation);
        return lines;
      }
      noteRenderFallback(state.degradation, "tool_render", JSON.stringify(rowShape(this)));
      return state.originalRender.call(this, width);
    }

    function rowFrom(row: ToolExecutionRow, _state: PatchState): ToolExecutionRow {
      return row;
    }

    function buildFromRow(
      row: ToolExecutionRow,
      state: PatchState,
      theme: ThemeLike,
      width: number,
    ): string[] | undefined {
      try {
        const snapshot = snapshotFromRow(row, state);
        if (!snapshot) return undefined;
        return buildCollapsedToolLines(snapshot, theme, width);
      } catch {
        return undefined;
      }
    }

    state.patchedRender = patchedRender;
    state.patchedUpdateDisplay = patchedUpdateDisplay;
    proto.render = patchedRender;
    proto.updateDisplay = patchedUpdateDisplay;
    Object.defineProperty(proto, PATCH_KEY, { configurable: true, value: state });
    return state;
  } catch {
    return undefined;
  }
}

function uninstall(state: PatchState | undefined): boolean {
  if (!state) return true;
  try {
    const proto = ToolExecutionComponent?.prototype as unknown as ProtoWithPatch | undefined;
    if (!proto) return true;
    // Never rip out another extension's wrapper sitting on top of ours.
    if (
      proto[PATCH_KEY] !== state ||
      proto.render !== state.patchedRender ||
      proto.updateDisplay !== state.patchedUpdateDisplay
    ) return false;
    proto.render = state.originalRender;
    proto.updateDisplay = state.originalUpdateDisplay;
    delete proto[PATCH_KEY];
    return true;
  } catch {
    return false;
  }
}

export function installToolRenderAdapter(
  getTheme: () => ThemeLike | undefined,
  timings: SessionState,
): boolean {
  return install(getTheme, timings) !== undefined;
}

// Synchronous, main-thread lifecycle only. Call uninstall only after this
// caller's successful install; false leaves the patch intact for safe retry.
export function uninstallToolRenderAdapter(): boolean {
  try {
    const proto = ToolExecutionComponent?.prototype as unknown as ProtoWithPatch | undefined;
    return uninstall(proto?.[PATCH_KEY]);
  } catch {
    // Restore failures must not break shutdown.
    return false;
  }
}

extensions.pi-ai-summary/src/adapters/thinking-labe:
// Adapter 2: AssistantMessageComponent.prototype.updateContent.
//
// RED LINES:
// - label decoration active ONLY in hidden-thinking mode
//   (row.hideThinkingBlock === true); visible thinking is a full
//   pass-through — no filtering, no deletion, no label rewriting (no
//   compact-ui-style suppression);
// - since v0.1.4 the adapter ALSO wraps render() for the final-answer
//   marker (see the marker section below): a display-only decoration built
//   from event-side state. It is OFF by default because moving the mark at
//   agent_end rewrites a row that is usually above the viewport, which
//   forces Pi's main screen into a full-session redraw (see the marker
//   preference section); the thinking label is kept byte-identical across
//   streaming/settle for the same reason; it never touches content;
// - default collapse happens through the display-layer row field
//   (hideThinkingBlock) ONLY — never through thinking level, request
//   parameters, or anything that influences model behavior (M-3);
// - the row-local label field must be assigned BEFORE the original
//   updateContent runs: the original builds the label Text node from the
//   field's value at build time (M-1);
// - display-copy only: combineAdjacentThinking never mutates the session
//   message or provider blocks.

import { AssistantMessageComponent } from "@earendil-works/pi-coding-agent";
import { existsSync, readFileSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import {
  buildThinkingLabel,
  combineAdjacentThinking,
  thinkingPreview,
  thinkingRuns,
} from "../summaries.ts";
import { leadingEscapePrefix, visibleWidth } from "../ansi.ts";
import { safeBg, safeFg, type ThemeLike } from "../theme.ts";
import {
  newFallbackTracker,
  noteRenderFallback,
  resetRenderFallback,
  type FallbackTracker,
} from "../events.ts";

const PATCH_KEY = Symbol.for("pi.aiSummary.thinkingLabel.v1");

// Thinking preview cap in visible columns (compact-ui's thinking-preview
// precedent value). updateContent has no terminal-width context; the label
// must stay single-line even on narrow terminals.
const THINKING_PREVIEW_MAX_COLS = 50;

type AssistantMessageRow = {
  hideThinkingBlock?: unknown;
  hiddenThinkingLabel?: unknown;
  updateContent: (message: unknown, ...args: unknown[]) => void;
};

type PatchState = {
  originalUpdateContent: (message: unknown, ...args: unknown[]) => void;
  originalRender: (width: number) => string[];
  patchedUpdateContent?: (message: unknown, ...args: unknown[]) => void;
  patchedRender?: (width: number) => string[];
  cwd: () => string | undefined;
  // Mirrors Pi's project-trust gate (ctx.isProjectTrusted()): when false,
  // the project-level settings file is ignored, global-only chain applies.
  projectTrusted: () => boolean;
  getTheme: () => ThemeLike | undefined;
  // Current accent-bar target: the final answer message OBJECT (deref of
  // state.finalAnswerRef) or undefined.
  getFinalAnswer: () => object | undefined;
  // Final-answer marker gate. When false (default) render() is a plain
  // pass-through and can never change an above-viewport row.
  markerActive: () => boolean;
  // Consecutive unexpected label-decoration failures → one-shot diag alert.
  degradation: FallbackTracker;
  // Row → message object, recorded in updateContent (all modes) so render()
  // can decide whether this row carries the final-answer accent bar.
  // Object identity: streaming messages have no stable id (verified).
  rowMessages: WeakMap<object, object | undefined>;
  // Rows this extension already evaluated for default-hidden adoption.
  adoptedRows: WeakSet<object>;
};

type ProtoWithPatch = AssistantMessageRow & {
  [PATCH_KEY]?: PatchState;
  updateContent?: (message: unknown, ...args: unknown[]) => void;
  render?: (width: number) => string[];
};

// ---------- default-hidden preference (Q1) ----------
//
// Runtime facts (verified against Pi's bundled source, v0.85.x):
// - `hideThinkingBlock` is a global setting, default false;
// - Ctrl+T (`app.thinking.toggle`) writes it to ~/.pi/agent/settings.json
//   immediately (setHideThinkingBlock → save()) and mutates existing rows
//   in place via row.setHideThinkingBlock(); rows are NOT rebuilt;
// - rows copy the setting at construction time.
//
// Therefore: force the row-local display field only when the user has never
// expressed a preference (key absent from project AND global settings). An
// explicit `false` anywhere means "user chose visible" and is respected.
// Settings files are stat-cached and re-read when their mtime changes, so a
// mid-session first Ctrl+T stops future adoption within one render.
//
// Scope data states (mirrors Pi's own settings-manager semantics):
// - file parses and has the key → that value wins, chain stops;
// - file parses without the key, or file missing → no data from this scope,
//   chain continues;
// - file unreadable/unparseable → no data, chain continues (Pi degrades a
//   corrupt scope to {} and keeps merging the rest — a corrupt project file
//   must not mask a valid global preference).
// Chain end: explicit key found → it; else if any scope was corrupted →
// "visible" (never force; matches Pi's degraded state); else "none" (fresh
// installs keep the default-collapse behavior).

// Effective preference after the precedence chain.
type Pref = "none" | "hidden" | "visible";

// Per-scope read result before chain resolution.
type RawPref = "hidden" | "visible" | "absent" | "corrupted";

// Settings locations mirror Pi's own precedence. Injectable for tests;
// production honors PI_CODING_AGENT_DIR and falls back to ~/.pi/agent.
const agentDir = process.env.PI_CODING_AGENT_DIR?.trim() || join(homedir(), ".pi", "agent");
let settingsPaths: { global: string; project?: string } = {
  global: join(agentDir, "settings.json"),
};

export function setSettingsPaths(globalPath: string, projectPath?: string): void {
  settingsPaths = { global: globalPath, project: projectPath };
  prefCache = undefined;
  markerCache = undefined;
}

function projectPathFor(cwd: string | undefined, projectTrusted: boolean): string | undefined {
  if (settingsPaths.project !== undefined) return settingsPaths.project;
  // Pi ignores project settings entirely for untrusted projects
  // (settings-manager.js loadFromStorage returns {} when projectTrusted is
  // false). Mirror that gate: an untrusted repo's .pi/settings.json must
  // not influence this extension's display behavior.
  if (!projectTrusted) return undefined;
  return cwd !== undefined ? join(cwd, ".pi", "settings.json") : undefined;
}

let prefCache: {
  globalPath: string;
  projectPath: string;
  globalMtimeMs: number;
  projectMtimeMs: number;
  pref: Pref;
} | undefined;

function readPrefFrom(path: string): RawPref {
  try {
    if (!existsSync(path)) return "absent";
    const parsed = JSON.parse(readFileSync(path, "utf8")) as Record<string, unknown>;
    if (!Object.hasOwn(parsed, "hideThinkingBlock")) return "absent";
    return parsed.hideThinkingBlock === true ? "hidden" : "visible";
  } catch {
    // Unreadable/unparseable scope: no data from this file — the chain
    // continues to the next precedence level. Forcing is only refused when
    // the whole chain ends without a key AND something was corrupted (M-5:
    // degradation follows Pi's current state).
    return "corrupted";
  }
}

function userPreference(cwd: string | undefined, projectTrusted: boolean): Pref {
  const globalPath = settingsPaths.global;
  const projectPath = projectPathFor(cwd, projectTrusted);

  const mtime = (path: string): number => {
    try {
      return statSync(path).mtimeMs;
    } catch {
      return -1;
    }
  };
  const globalMtimeMs = mtime(globalPath);
  const projectMtimeMs = projectPath ? mtime(projectPath) : -1;

  if (
    prefCache &&
    prefCache.globalPath === globalPath &&
    prefCache.projectPath === (projectPath ?? "") &&
    prefCache.globalMtimeMs === globalMtimeMs &&
    prefCache.projectMtimeMs === projectMtimeMs
  ) {
    return prefCache.pref;
  }

  // Project overrides global, mirroring Pi's own precedence.
  let corrupted = false;
  let pref: Pref = "none";
  const sources = projectPath ? [projectPath, globalPath] : [globalPath];
  for (const path of sources) {
    const raw = readPrefFrom(path);
    if (raw === "hidden" || raw === "visible") {
      pref = raw;
      break;
    }
    if (raw === "corrupted") corrupted = true;
  }
  if (pref === "none" && corrupted) pref = "visible";

  prefCache = {
    globalPath,
    projectPath: projectPath ?? "",
    globalMtimeMs,
    projectMtimeMs,
    pref,
  };
  return pref;
}

// ---------- final-answer marker preference ----------
//
// Why this is a setting: the marker can force Pi's MAIN-SCREEN renderer into
// a full redraw (the thinking label used to be a second path — appending the
// duration/token tail at settle rewrote an above-viewport row; it is now
// byte-identical across phases). At agent_end the target moves to
// the new answer; the previous answer is by then usually above the visible
// viewport, and ANY byte change above the viewport makes TuiMainScreen call
// fullRender(true) — it clears the scrollback (ESC[3J) and reprints the whole
// session. A marked answer taller than one screen triggers the same on its
// first render. There is no way to keep "only the latest answer is marked"
// AND never touch an above-viewport row, so the marker defaults to OFF.
// Fullscreen (alt-screen) renders into previousScreen with no scrollback and
// no history-wide diff, so there it is safe.
//
// Setting (<settings.json>): "piAiSummary": { "finalAnswerMarker": ... }
//   "off"        — default; no marker, render() is a plain pass-through
//   "fullscreen" — marker only when tuiMode === "fullscreen"
//   "always"     — marker in every mode (accepts the main-screen redraw)
// Precedence mirrors hideThinkingBlock: project (if trusted) overrides global.
type MarkerMode = "off" | "fullscreen" | "always";

let markerCache: {
  globalPath: string;
  projectPath: string;
  globalMtimeMs: number;
  projectMtimeMs: number;
  settings: Record<string, unknown>;
} | undefined;

function readSettingsObject(path: string | undefined): Record<string, unknown> | undefined {
  if (path === undefined) return undefined;
  try {
    const parsed = JSON.parse(readFileSync(path, "utf8")) as unknown;
    return typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

function mergedSettings(cwd: string | undefined, projectTrusted: boolean): Record<string, unknown> {
  const globalPath = settingsPaths.global;
  const projectPath = projectPathFor(cwd, projectTrusted);
  const mtime = (path: string | undefined): number => {
    if (path === undefined) return -1;
    try {
      return statSync(path).mtimeMs;
    } catch {
      return -1;
    }
  };
  const globalMtimeMs = mtime(globalPath);
  const projectMtimeMs = mtime(projectPath);

  if (
    markerCache &&
    markerCache.globalPath === globalPath &&
    markerCache.projectPath === (projectPath ?? "") &&
    markerCache.globalMtimeMs === globalMtimeMs &&
    markerCache.projectMtimeMs === projectMtimeMs
  ) {
    return markerCache.settings;
  }

  // Top-level project keys override global, then the whole object is cached.
  const settings: Record<string, unknown> = {};
  const globalObject = readSettingsObject(globalPath);
  if (globalObject) Object.assign(settings, globalObject);
  const projectObject = readSettingsObject(projectPath);
  if (projectObject) Object.assign(settings, projectObject);

  markerCache = {
    globalPath,
    projectPath: projectPath ?? "",
    globalMtimeMs,
    projectMtimeMs,
    settings,
  };
  return settings;
}

function finalAnswerMarkerMode(cwd: string | undefined, projectTrusted: boolean): MarkerMode {
  const namespace = mergedSettings(cwd, projectTrusted).piAiSummary;
  if (typeof namespace !== "object" || namespace === null || Array.isArray(namespace)) {
    return "off";
  }
  const value = (namespace as Record<string, unknown>).finalAnswerMarker;
  return value === "always" || value === "fullscreen" ? value : "off";
}

// The single gate consulted by render(): false means the marker decorations
// are never produced, so no above-viewport row can ever be rewritten.
function isFinalAnswerMarkerActive(cwd: string | undefined, projectTrusted: boolean): boolean {
  const mode = finalAnswerMarkerMode(cwd, projectTrusted);
  if (mode === "always") return true;
  if (mode !== "fullscreen") return false;
  return mergedSettings(cwd, projectTrusted).tuiMode === "fullscreen";
}

// Only new rows reach here (adoptedRows gate). In-session Ctrl+T mutates
// rows in place, and marked rows never get re-forced — the user's toggle
// always wins.
function maybeAdoptDefaultHidden(row: AssistantMessageRow, state: PatchState): void {
  if (state.adoptedRows.has(row)) return;
  state.adoptedRows.add(row);
  if (row.hideThinkingBlock !== false) return; // native-hidden or unknown shape
  const pref = userPreference(state.cwd(), state.projectTrusted());
  if (pref === "hidden") {
    row.hideThinkingBlock = true;
    return;
  }
  if (pref !== "none") return; // explicit visible, or corrupted-chain fallback → Pi's state
  // M-3: display-layer field only.
  row.hideThinkingBlock = true;
}

// ---------- label ----------

function applyRowLabel(row: AssistantMessageRow, message: { content?: unknown }): void {
  const content = message?.content;
  if (!Array.isArray(content)) return;
  const runs = thinkingRuns(content);
  if (runs.length === 0) return; // no thinking yet → keep the native label

  const preview = thinkingPreview(runs[0]!, THINKING_PREVIEW_MAX_COLS);

  // Known v1 limitation: a message with multiple text-separated thinking
  // runs shares this single label string for all of its collapsed runs.
  // Label is byte-identical while streaming and after settle (no timer /
  // token tail): see buildThinkingLabel.
  row.hiddenThinkingLabel = buildThinkingLabel({ preview });
}

// ---------- final-answer marker (v0.1.4 bar → v0.1.6 bg) ----------
//
// Marks the latest turn's final text answer at render() time from
// event-side state, all modes, display-layer only.
//
// Primary form (v0.1.6): full-row background tint with the official
// Theme.bg API, customMessageBg token — no extra characters, no column
// reservation (same mechanism as official tool/user message rows).
// Degradation form (v0.1.4, kept until long-term stability is proven):
// left accent bar ("▌" + space = 2 columns; original render runs at
// width - 2) when the theme lacks bg support or bg fails.
//
// The previous answer keeps the marker while the next turn streams; the
// marker moves at agent_end. Restored sessions have no event state → no
// marker until the next turn ends. Old rows lose the marker on their next
// repaint (render reads current state every call).


const BAR = "▌";
// No dedicated "assistant answer" bg token exists in ThemeBg; the custom-
// message tint is the closest semantic match (user decision, v0.1.6).
const ANSWER_BG_TOKEN = "customMessageBg";

function hasBg(theme: ThemeLike | undefined): boolean {
  return typeof theme?.bg === "function";
}

function withAnswerBg(
  lines: string[],
  getTheme: () => ThemeLike | undefined,
  width: number,
): string[] {
  // Official applyBackgroundToLine semantics: pad to full width, then wrap
  // the whole line in the background color. Zero-width escape prefixes
  // (OSC133 zone markers) stay outside the colored span.
  // Leading blank lines are the component's own Spacer(1): leave them
  // untinted so the gap to the previous message keeps the default
  // background (v0.1.7 — the tint used to swallow the separation).
  let first = 0;
  while (first < lines.length) {
    const esc = leadingEscapePrefix(lines[first]!);
    if (visibleWidth(lines[first]!.slice(esc.length)) > 0) break;
    first++;
  }
  if (first === lines.length) return lines;
  // Keep the native outer gap; add theme-colored padding INSIDE the block.
  // Build a fresh array so repeated renders never accumulate blank rows.
  const withPadding = [...lines.slice(0, first), "", ...lines.slice(first), ""];
  return withPadding.map((line, index) => {
    if (index < first) return line;
    const esc = leadingEscapePrefix(line);
    const content = line.slice(esc.length);
    const padded = content + " ".repeat(Math.max(0, width - visibleWidth(content)));
    const wrapped = safeBg(getTheme(), ANSWER_BG_TOKEN, padded);
    if (wrapped === padded) {
      // safeBg swallowed a failure → bg unavailable: bubble up so the
      // caller degrades to the accent bar instead of a silent no-marker.
      throw new Error("answer bg unavailable");
    }
    return esc + wrapped;
  });
}

function withAccentBar(lines: string[], getTheme: () => ThemeLike | undefined): string[] {
  return lines.map((line) => {
    // Zero-width escape prefix (OSC133 zone markers etc.) stays first so
    // the bar lands after it, inside the marked zone.
    const esc = leadingEscapePrefix(line);
    return `${esc}${safeFg(getTheme(), "accent", BAR)} ${line.slice(esc.length)}`;
  });
}

// ---------- patch ----------

function install(
  cwd: () => string | undefined,
  projectTrusted: () => boolean,
  getTheme: () => ThemeLike | undefined,
  getFinalAnswer: () => object | undefined,
): PatchState | undefined {
  try {
    const proto = AssistantMessageComponent?.prototype as unknown as ProtoWithPatch | undefined;
    if (
      !proto ||
      typeof proto.updateContent !== "function" ||
      typeof proto.render !== "function"
    ) {
      return undefined;
    }

    // Single-instance contract: never reuse another installation's state.
    if (proto[PATCH_KEY]) return undefined;

    const state: PatchState = {
      originalUpdateContent: proto.updateContent,
      originalRender: proto.render,
      cwd,
      projectTrusted,
      getTheme,
      getFinalAnswer,
      markerActive: () => isFinalAnswerMarkerActive(cwd(), projectTrusted()),
      degradation: newFallbackTracker(),
      rowMessages: new WeakMap(),
      adoptedRows: new WeakSet(),
    };

    const patchedRender = function renderWithFinalAnswerMarker(
      this: AssistantMessageRow,
      width: number,
    ): string[] {
      let marked = false;
      try {
        const final = state.getFinalAnswer();
        marked =
          final !== undefined &&
          state.rowMessages.get(this) === final &&
          state.markerActive();
      } catch {
        return state.originalRender.call(this, width);
      }
      if (!marked) return state.originalRender.call(this, width);
      // Primary: full-row background tint (official Theme.bg mechanism),
      // no extra characters, no column reservation. Falls through to the
      // accent bar when the theme lacks bg support or bg fails.
      if (hasBg(state.getTheme())) {
        try {
          return withAnswerBg(state.originalRender.call(this, width), state.getTheme, width);
        } catch {
          // Fall through to the bar.
        }
      }
      // Degradation: accent bar, 2 columns reserved.
      const lines = state.originalRender.call(this, Math.max(1, width - 2));
      try {
        return withAccentBar(lines, state.getTheme);
      } catch {
        return lines;
      }
    };

    const patchedUpdateContent = function updateContentWithThinkingLabel(
      this: AssistantMessageRow,
      message: unknown,
      ...args: unknown[]
    ): void {
      // Record row → message object (all modes) for the accent-bar decision.
      try {
        if (message !== null && typeof message === "object") {
          state.rowMessages.set(this, message);
        }
      } catch {
        // Bar decision is best-effort.
      }

      // ① Visible mode (user's choice or Pi's current state) → full
      //    pass-through for the LABEL; the accent bar is applied in
      //    render(), independent of this branch.
      if (this.hideThinkingBlock !== true) {
        try {
          maybeAdoptDefaultHidden(this, state);
        } catch {
          // Adoption is best-effort; keep Pi's state on any failure.
        }
        if (this.hideThinkingBlock !== true) {
          return Reflect.apply(state.originalUpdateContent, this, [message, ...args]);
        }
      }

      // ② Row-local label BEFORE the original call: the original reads
      //    hiddenThinkingLabel while building its Text nodes.
      try {
        applyRowLabel(this, (message ?? {}) as { content?: unknown });
        resetRenderFallback(state.degradation);
      } catch {
        noteRenderFallback(state.degradation, "thinking_label", "applyRowLabel failed");
        // Keep Pi's native label when the row shape changes.
      }

      // ③ Original builds from a display-copy with adjacent thinking
      //    merged; the session message is never modified.
      let displayMessage = message;
      try {
        const content = (message as { content?: readonly unknown[] } | undefined)?.content;
        const merged = Array.isArray(content) ? combineAdjacentThinking(content) : undefined;
        if (merged) displayMessage = { ...(message as object), content: merged };
      } catch {
        // Preserve the original message intact.
      }
      Reflect.apply(state.originalUpdateContent, this, [displayMessage, ...args]);

      // ④ No node-level restyle needed: Pi's native hidden label already
      //    renders with the thinkingText token (italic).
    };

    state.patchedUpdateContent = patchedUpdateContent;
    state.patchedRender = patchedRender;
    proto.updateContent = patchedUpdateContent;
    proto.render = patchedRender;
    Object.defineProperty(proto, PATCH_KEY, { configurable: true, value: state });
    return state;
  } catch {
    return undefined;
  }
}

function uninstall(state: PatchState | undefined): boolean {
  if (!state) return true;
  try {
    const proto = AssistantMessageComponent?.prototype as unknown as ProtoWithPatch | undefined;
    if (!proto) return true;
    if (
      proto[PATCH_KEY] !== state ||
      proto.updateContent !== state.patchedUpdateContent ||
      proto.render !== state.patchedRender
    ) {
      return false;
    }
    proto.updateContent = state.originalUpdateContent;
    proto.render = state.originalRender;
    delete proto[PATCH_KEY];
    return true;
  } catch {
    return false;
  }
}

export function installThinkingLabelAdapter(
  cwd: () => string | undefined,
  // Fail-closed by default: without a real probe, project settings are
  // ignored and only the global chain applies. Production (index.ts)
  // always passes the real ctx.isProjectTrusted() probe; tests pass an
  // explicit () => true when they exercise the project chain.
  projectTrusted: () => boolean = () => false,
  getTheme: () => ThemeLike | undefined = () => undefined,
  getFinalAnswer: () => object | undefined = () => undefined,
): boolean {
  return install(cwd, projectTrusted, getTheme, getFinalAnswer) !== undefined;
}

// Synchronous, main-thread lifecycle only. Call uninstall only after this
// caller's successful install; false leaves the patch intact for safe retry.
export function uninstallThinkingLabelAdapter(): boolean {
  try {
    const proto = AssistantMessageComponent?.prototype as unknown as ProtoWithPatch | undefined;
    return uninstall(proto?.[PATCH_KEY]);
  } catch {
    // Restore failures must not break shutdown.
    return false;
  }
}

extensions.pi-handoff-gate/allcopy.ts:
/**
 * pi-handoff-gate `/allcopy` 纯函数模块。
 *
 * 输入当前会话分支的 SessionEntry 列表（root→leaf），按确定性结构标记筛选出
 * "最近一个任务范围"**中 assistant 的回答内容**（逐轮答复 + 最终回复）并组装剪贴板
 * 文本。用户发言只用作起点定位，不进入剪贴板。不做任何语义判断、不调用模型、
 * 不改写原文。
 *
 * 实测依据（Pi 0.87.1，SessionEntry 结构）：
 * - 真实用户消息：entry.type === "message" && entry.message.role === "user"；
 * - 扩展注入消息：entry.type === "custom_message"（独立类型，天然不是用户消息）；
 *   它同时是**轮次边界**（handoff-gate 的续跑催促、pi-agent-resilience 的续跑边界）；
 * - report_to_user 调用：assistant message.content 中
 *   { type: "toolCall", name: "report_to_user", arguments: { kind, summary } }；
 *   同一 assistant 消息可同时含 text 与 toolCall；
 * - 终态交接后，实际收尾文本位于其后的一条 assistant 消息（通常无 toolCall）。
 *
 * 逐轮取法：范围内被 custom_message 切开的每一轮里，取
 * ① 含 report_to_user 调用的 assistant 正文（阶段汇报）；② 该轮最后一条非空 assistant 正文（该轮收尾）。
 * 二者去重后按时间顺序进入 `rounds`；整个范围的最后一条（终态交接之后）作为 `finalReply`。
 * 这样就不会把同一范围内前面几轮的汇报丢掉（旧版只保留 milestone 标记与最后一条）。
 *
 * 本模块不依赖 Pi 运行时：仅 `import type`，运行时被剥离，可用 node --test 直测。
 */

import type { SessionEntry } from "@earendil-works/pi-coding-agent";
import { REPORT_TOOL_NAME } from "./gate.ts";

/** 会交还控制权的终态交接类别（milestone 是阶段完成，不终止本次任务） */
const TERMINAL_KINDS = new Set(["decision", "blocked", "done"]);

const FALLBACK_NOTE = "注——最终回复未可靠识别，取自最后一条 assistant 正文";
const ROUND_SEPARATOR = "\n\n---\n\n";

/** 结构化的摘要结果（供终端统计与测试断言） */
export interface AllcopyResult {
  /** 状态行内容（见组装格式） */
  status: string;
  /** 是否定位到任务起点（最近一条真实用户消息）；仅用于边界与状态 */
  anchorFound: boolean;
  /** 任务起点原文；仅用于定位/调试，**不进入剪贴板文本** */
  userRequest: string | null;
  /** 轮次回答正文（按时间顺序；已去掉与最终回复重复的那条） */
  rounds: string[];
  /** 最终回复正文；null 表示未找到 */
  finalReply: string | null;
  /** 最终回复是否可靠识别（false 即走了回退规则） */
  finalReplyReliable: boolean;
  /** 警告列表（milestone 正文为空、边界不确定等） */
  warnings: string[];
  /** 组装好的剪贴板文本；无任何保留内容时为空串 */
  text: string;
  /** text 的字符数（按 Unicode 码点计） */
  charCount: number;
}

type AnyEntry = SessionEntry & {
  type: string;
  id?: string;
  message?: { role?: string; content?: unknown };
  customType?: string;
  firstKeptEntryId?: string;
};

interface ContentBlock {
  type?: unknown;
  text?: unknown;
  name?: unknown;
  arguments?: unknown;
}

function blocksOf(content: unknown): ContentBlock[] {
  if (typeof content === "string") return [{ type: "text", text: content }];
  if (Array.isArray(content)) return content as ContentBlock[];
  return [];
}

function entryBlocks(entry: AnyEntry): ContentBlock[] {
  return blocksOf(entry.message?.content);
}

/** 取 content 中所有非空 text 块，按原顺序以空行连接；不含 thinking / toolCall。 */
function textOfBlocks(blocks: readonly ContentBlock[]): string {
  const parts: string[] = [];
  for (const b of blocks) {
    if (b && b.type === "text" && typeof b.text === "string" && b.text.length > 0) {
      parts.push(b.text);
    }
  }
  return parts.join("\n\n");
}

function isMessageEntry(entry: AnyEntry): boolean {
  return entry.type === "message";
}

function isUserMessage(entry: AnyEntry): boolean {
  return isMessageEntry(entry) && entry.message?.role === "user";
}

function isAssistantMessage(entry: AnyEntry): boolean {
  return isMessageEntry(entry) && entry.message?.role === "assistant";
}

/** 从 toolCall.arguments 读出 kind；arguments 可能是对象或 JSON 字符串。 */
function readReportKind(args: unknown): string | null {
  let value = args;
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  }
  if (value && typeof value === "object") {
    const kind = (value as { kind?: unknown }).kind;
    if (typeof kind === "string") return kind;
  }
  return null;
}

/** 该 assistant 消息中全部 report_to_user 调用的 kind 列表（按出现顺序）。 */
function reportKinds(blocks: readonly ContentBlock[]): string[] {
  const kinds: string[] = [];
  for (const b of blocks) {
    if (b && b.type === "toolCall" && b.name === REPORT_TOOL_NAME) {
      const kind = readReportKind(b.arguments);
      if (kind !== null) kinds.push(kind);
    }
  }
  return kinds;
}

function hasAnyToolCall(blocks: readonly ContentBlock[]): boolean {
  return blocks.some((b) => b && b.type === "toolCall");
}

/**
 * 复刻 Pi 0.87.1 buildContextEntries 的压缩归约（输入已是当前分支路径）：
 * 以最后一个 compaction 条目为准，丢弃 firstKeptEntryId 之前的条目。
 * 返回 active（可见条目）与被压缩替代的 lost（其前的原始条目）。
 */
export function reduceActiveEntries(entries: readonly SessionEntry[]): {
  active: AnyEntry[];
  lost: AnyEntry[];
} {
  const path = entries as AnyEntry[];
  let compaction: AnyEntry | null = null;
  for (const e of path) {
    if (e.type === "compaction") compaction = e;
  }
  if (!compaction) return { active: [...path], lost: [] };

  const ci = path.findIndex((e) => e.id === compaction!.id);
  if (ci < 0) return { active: [...path], lost: [] };

  const firstKeptId = compaction.firstKeptEntryId;
  let firstKeptIdx = ci;
  if (typeof firstKeptId === "string") {
    const idx = path.findIndex((e) => e.id === firstKeptId);
    if (idx >= 0) firstKeptIdx = idx;
  }

  const lost = path.slice(0, firstKeptIdx);
  const active = [compaction, ...path.slice(firstKeptIdx, ci), ...path.slice(ci + 1)];
  return { active, lost };
}

/** 从 active 中定位最近一条真实用户消息的下标；找不到返回 -1。 */
export function findLastUserIndex(active: readonly SessionEntry[]): number {
  const path = active as AnyEntry[];
  for (let i = path.length - 1; i >= 0; i--) {
    if (isUserMessage(path[i])) return i;
  }
  return -1;
}

/** 组装"状态"行：终态基础 + 边界补充。 */
function buildStatus(
  terminalKind: string | null,
  boundary: readonly string[],
): string {
  let basis: string;
  if (terminalKind === "done") basis = "正常完成";
  else if (terminalKind === "decision") basis = "任务尚未确认结束（等待用户决策）";
  else if (terminalKind === "blocked") basis = "任务尚未确认结束（任务阻塞）";
  else basis = "任务尚未确认结束（未检测到终态交接）";

  if (boundary.length === 0) return basis;
  return `${basis}；边界不完整（${boundary.join("；")}）`;
}

/**
 * 主入口：从当前分支条目组装任务范围记录。
 *
 * 规则（确定性，结构标记优先）：
 * - 起点：最近一条真实用户消息，**只用于定位范围边界与状态，不进入剪贴板**；
 * - 轮次：范围内以扩展注入消息（`custom_message`）切轮，逐轮取该轮 agent 的答复；
 * - 阶段总结：含 report_to_user(kind=milestone) 的 assistant 消息的 text 部分；
 * - 最终回复：终态交接（decision/blocked/done）之后、无后续工具调用的最后一条
 *   assistant 文本；无法可靠识别时回退到最后一条 assistant 文本并标注；
 * - 其余 assistant 正文、thinking、toolCall 参数、toolResult、custom_message、
 *   会话元数据一律排除。
 */
export function buildAllcopyText(entries: readonly SessionEntry[]): AllcopyResult {
  const warnings: string[] = [];
  const boundary: string[] = [];

  const { active, lost } = reduceActiveEntries(entries);

  // 起点：仅用于定位范围边界与状态判定，不进入剪贴板文本。
  const userIdx = findLastUserIndex(active);
  const anchorFound = userIdx >= 0;
  const userRequest = anchorFound ? textOfBlocks(entryBlocks(active[userIdx])) || null : null;
  if (!anchorFound) {
    warnings.push("任务起点无法确定（当前可见范围内未找到真实用户消息）");
    boundary.push("任务起点无法确定");
  }

  // 压缩替代提示：仅当起点确实未定位时才成立。
  // 若 anchorFound 为真，则最近一条真实用户消息在可见范围内（压缩丢弃的是前缀，
  // 最后一条用户消息若被丢弃，可见范围内就不会有任何用户消息 → anchorFound 必为 false），
  // 此时被压缩掉的用户消息属于更早的任务，按口径本就不收录，不应再计入边界。
  const lostUserCount = lost.filter(isUserMessage).length;
  if (!anchorFound && lostUserCount > 0) {
    const note = `任务起点可能已被压缩替代（压缩前有 ${lostUserCount} 条用户消息），汇总仅覆盖压缩后内容`;
    warnings.push(note);
    boundary.push("任务起点可能已被压缩替代");
  }

  const range = userIdx >= 0 ? active.slice(userIdx) : active;

  // 轮次切分：扩展注入消息（custom_message：handoff-gate 的续跑催促、pi-agent-resilience 的续跑边界）
  // 把范围切成若干“轮”。逐轮取该轮 agent 的答复——
  //   ① 含 report_to_user 调用的 assistant 正文（阶段汇报）；
  //   ② 该轮最后一条非空 assistant 正文（该轮收尾答复）。
  // 两者去重后按时间顺序进入 answers；用户发言不进入文本（仅用于定位起点）。
  const answers: string[] = [];
  const seenAnswers = new Set<string>();
  const pushAnswer = (text: string): void => {
    if (text.length === 0 || seenAnswers.has(text)) return;
    seenAnswers.add(text);
    answers.push(text);
  };
  let segment: AnyEntry[] = [];
  const flushSegment = (): void => {
    if (segment.length === 0) return;
    let closing: string | null = null;
    for (const entry of segment) {
      if (!isAssistantMessage(entry)) continue;
      const blocks = entryBlocks(entry);
      const text = textOfBlocks(blocks);
      if (text.length === 0) continue;
      if (reportKinds(blocks).length > 0) pushAnswer(text);
      closing = text;
    }
    if (closing !== null) pushAnswer(closing);
    segment = [];
  };
  for (const entry of range) {
    if ((entry as AnyEntry).type === "custom_message") flushSegment();
    else segment.push(entry as AnyEntry);
  }
  flushSegment();

  // 终态交接标记
  let terminalIdx = -1;
  let terminalKind: string | null = null;
  for (let i = 0; i < range.length; i++) {
    if (!isAssistantMessage(range[i])) continue;
    for (const kind of reportKinds(entryBlocks(range[i]))) {
      if (TERMINAL_KINDS.has(kind)) {
        terminalIdx = i;
        terminalKind = kind;
      }
    }
  }

  // 最终回复
  let finalReply: string | null = null;
  let finalReplyReliable = false;
  if (terminalIdx >= 0) {
    let continued = false;
    let candidate: string | null = null;
    for (let i = terminalIdx + 1; i < range.length; i++) {
      if (!isAssistantMessage(range[i])) continue;
      const blocks = entryBlocks(range[i]);
      if (hasAnyToolCall(blocks)) continued = true;
      const text = textOfBlocks(blocks);
      if (text.length > 0) candidate = text;
    }
    if (candidate !== null) {
      finalReply = candidate;
      if (continued) {
        warnings.push(
          "终态交接后模型仍有工具调用（任务可能被续跑），最终回复取自其后最后一条 assistant 文本",
        );
      } else {
        finalReplyReliable = true;
      }
    }
  }

  if (finalReply === null) {
    for (let i = range.length - 1; i >= 0; i--) {
      if (!isAssistantMessage(range[i])) continue;
      const text = textOfBlocks(entryBlocks(range[i]));
      if (text.length > 0) {
        finalReply = text;
        break;
      }
    }
    if (finalReply !== null) {
      warnings.push("最终回复未可靠识别，取自最后一条 assistant 文本");
      boundary.push("最终回复未可靠识别");
    } else {
      warnings.push("未找到最终回复");
      boundary.push("未找到最终回复");
    }
  }

  const status = buildStatus(terminalKind, boundary);

  // 轮次回答 = 全部轮次答复去掉“最终回复”那一条（避免与“最终回复”章重复）。
  const rounds = [...answers];
  if (finalReply !== null) {
    const idx = rounds.lastIndexOf(finalReply);
    if (idx >= 0) rounds.splice(idx, 1);
  }

  // 组装：仅收录 assistant 回答（逐轮回答 + 最终回复）；用户发言只用于定位起点，不进入文本
  const parts: string[] = ["# Pi Agent 任务记录", "", `状态：${status}`];
  if (rounds.length > 0) {
    parts.push("", `## 轮次回答（${rounds.length} 条）`, "", rounds.join(ROUND_SEPARATOR));
  }
  if (finalReply !== null) {
    parts.push("", "## 最终回复", "");
    if (!finalReplyReliable) parts.push(FALLBACK_NOTE);
    parts.push(finalReply);
  }

  const hasContent = rounds.length > 0 || finalReply !== null;
  const text = hasContent ? `${parts.join("\n")}\n` : "";

  return {
    status,
    anchorFound,
    userRequest,
    rounds,
    finalReply,
    finalReplyReliable,
    warnings,
    text,
    charCount: [...text].length,
  };
}

/** 终端统计文本：只输出统计与警告，不含正文。 */
export function formatAllcopyStats(result: AllcopyResult): string {
  const lines = [
    "/allcopy 已复制到剪贴板",
    result.anchorFound
      ? "任务起点：已定位（用户发言未收录）"
      : "任务起点：未定位",
    `轮次回答：${result.rounds.length} 条`,
    result.finalReply === null
      ? "最终回复：未找到"
      : `最终回复：已识别${result.finalReplyReliable ? "" : "（回退规则，未可靠识别）"}`,
    `汇总字符数：${result.charCount}`,
    `任务状态：${result.status}`,
    result.warnings.length === 0
      ? "警告：无"
      : `警告：\n- ${result.warnings.join("\n- ")}`,
  ];
  return lines.join("\n");
}

extensions.pi-handoff-gate/todo.ts:
/**
 * pi-handoff-gate 的 Todo 纯函数模块。
 *
 * 不依赖 Pi 运行时，可直接 node --test 单测。
 * 状态由 index.ts 闭包持有；持久化用工具结果 details（随会话分支），
 * 在 session_start / session_tree 由 index.ts 从 getBranch() 重建。
 *
 * 设计取舍：
 * - 支持 set / update / advance / clear 四种状态迁移（任务口径：多步任务先 set 清单，
 *   推进时优先用 advance，一步完成“当前项 done + 下一项 in_progress”）。
 *   不支持逐条 add，避免 id 分配与重建时的 nextId 语义复杂化：
 *   set 时按顺序重编号为 1..n，重建只需最后一份快照。
 * - set 时自动把第一项标为 in_progress（面板一开始就能显示“当前环节”）。
 * - `skipped` 是终态（与 done 一样不计入未完成项），用于模型判定无法完成的项。
 * - reduce 返回“新状态或错误”，自身不改入参（纯函数，便于单测与分支重建）。
 */

export type TodoStatus = "pending" | "in_progress" | "done" | "skipped" | "blocked";

/** Todo 工具名；index.ts 注册与此同名，持久化/重建都以此筛选 toolResult */
export const TODO_TOOL_NAME = "todo";

/** 用户命令 `/todo clear` 等非工具变更的持久化 custom entry 名（不进模型上下文） */
export const TODO_ENTRY_NAME = "pi-handoff-gate-todo";

export interface TodoItem {
  id: number;
  text: string;
  status: TodoStatus;
}

export interface TodoState {
  items: TodoItem[];
}

export const EMPTY_TODO_STATE: TodoState = { items: [] };

export type TodoAction =
  | { type: "set"; items: string[] }
  | { type: "update"; id: number; status?: TodoStatus; text?: string }
  | { type: "advance" }
  | { type: "clear" };

export type ReduceResult =
  | { ok: true; state: TodoState }
  | { ok: false; state: TodoState; error: string };

const STATUSES: readonly TodoStatus[] = ["pending", "in_progress", "done", "skipped", "blocked"];

export function isTodoStatus(value: unknown): value is TodoStatus {
  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
}

/** 校验外部数据（工具结果 details 重建 / 参数透传）是否为合法 TodoState */
export function isTodoState(value: unknown): value is TodoState {
  if (value === null || typeof value !== "object") return false;
  const items = (value as { items?: unknown }).items;
  if (!Array.isArray(items)) return false;
  return items.every((item) => {
    if (item === null || typeof item !== "object") return false;
    const it = item as { id?: unknown; text?: unknown; status?: unknown };
    return (
      typeof it.id === "number" &&
      Number.isSafeInteger(it.id) &&
      typeof it.text === "string" &&
      isTodoStatus(it.status)
    );
  });
}

/**
 * 状态迁移。非法动作（如 update 的 id 不存在）返回 ok:false 与原状态，
 * 调用方负责把 error 反馈给模型。
 */
export function reduce(state: TodoState, action: TodoAction): ReduceResult {
  switch (action.type) {
    case "set": {
      const texts = Array.isArray(action.items) ? action.items : [];
      const items: TodoItem[] = texts
        .map((text) => (typeof text === "string" ? text.trim() : ""))
        .filter((text) => text.length > 0)
        .map((text, index) => ({ id: index + 1, text, status: "pending" }));
      // 建清单时自动把第一项标为进行中（已有 in_progress 时不改，实际 set 后恒无）
      if (items.length > 0 && !items.some((it) => it.status === "in_progress")) {
        items[0] = { ...items[0], status: "in_progress" };
      }
      return { ok: true, state: { items } };
    }
    case "advance": {
      // 一步推进：当前 in_progress → done；下一个 pending → in_progress。
      // 无 in_progress → 只把第一个 pending 置 in_progress；无 pending → 只完成当前项。
      const items = state.items.map((it) => ({ ...it }));
      const cur = items.findIndex((it) => it.status === "in_progress");
      if (cur >= 0) items[cur].status = "done";
      const next = items.findIndex((it) => it.status === "pending");
      if (next >= 0) items[next].status = "in_progress";
      return { ok: true, state: { items } };
    }
    case "update": {
      const exists = state.items.some((it) => it.id === action.id);
      if (!exists) {
        return { ok: false, state, error: `todo #${action.id} 不存在` };
      }
      const trimmed = typeof action.text === "string" ? action.text.trim() : undefined;
      const items = state.items.map((it) =>
        it.id === action.id
          ? {
              ...it,
              status: action.status ?? it.status,
              text: trimmed && trimmed.length > 0 ? trimmed : it.text,
            }
          : it,
      );
      return { ok: true, state: { items } };
    }
    case "clear":
      return { ok: true, state: EMPTY_TODO_STATE };
  }
}

/** 未完成项：pending / in_progress / blocked；done 与 skipped 为终态 */
export function openItems(state: TodoState): TodoItem[] {
  return state.items.filter(
    (it) => it.status === "pending" || it.status === "in_progress" || it.status === "blocked",
  );
}

export function hasOpenItems(state: TodoState): boolean {
  return openItems(state).length > 0;
}

/** 当前进行中的项（第一个 in_progress）；无则 undefined */
export function currentInProgress(state: TodoState): TodoItem | undefined {
  return state.items.find((it) => it.status === "in_progress");
}

/** 下一个待办项（第一个 pending）；advance 会把它标为进行中 */
export function nextPending(state: TodoState): TodoItem | undefined {
  return state.items.find((it) => it.status === "pending");
}

const MARK: Record<TodoStatus, string> = {
  pending: "[ ]",
  in_progress: "[~]",
  done: "[x]",
  skipped: "[-]",
  blocked: "[!]",
};

/** settle 续跑 nudge 里附带剩余清单的上限 */
export const NUDGE_TODO_LIMIT = 10;

/** 仅未完成项的紧凑文本（用于 nudge）；无未完成项返回空串；超过 limit 时标注剩余数 */
export function renderOpenItems(state: TodoState, limit: number = NUDGE_TODO_LIMIT): string {
  const open = openItems(state);
  if (open.length === 0) return "";
  const shown = open.slice(0, Math.max(0, limit));
  const lines = shown.map((it) => `${MARK[it.status]} #${it.id} ${it.text}`);
  if (open.length > shown.length) {
    lines.push(`…还有 ${open.length - shown.length} 项未列出`);
  }
  return lines.join("\n");
}

/** settle 催促里「清单陈旧」提醒的默认阈值（自上次 todo 调用以来累计的其它工具调用数；0 = 关闭） */
export const DEFAULT_TODO_STALE_CALLS = 12;

/** 同一 run 内「清单未同步」中途提醒（turn_end 注入）的次数上限 */
export const TODO_REMINDER_LIMIT = 3;

/**
 * 中途提醒文本（turn_end 注入；纯函数，便于单测）。
 *
 * 返回非空串的条件（全部满足）：
 * - threshold > 0（阈值 0 = 关闭）；
 * - 本次 run 已提醒次数 < TODO_REMINDER_LIMIT；
 * - 清单仍有未完成项；
 * - sinceTodoCalls >= threshold；
 * - 若有历史提醒，则与上次提醒时相比至少又多了 threshold 次调用（两提醒间至少隔一个阈值）。
 * 内容：当前进行中项 + 下一项，并建议 advance / update。
 */
export function todoAdvanceReminder(
  state: TodoState,
  sinceTodoCalls: number,
  threshold: number,
  remindersSent: number,
  lastReminderAt: number,
): string {
  if (!Number.isFinite(threshold) || threshold <= 0) return "";
  if (!Number.isSafeInteger(remindersSent) || remindersSent >= TODO_REMINDER_LIMIT) return "";
  if (!hasOpenItems(state)) return "";
  if (!Number.isSafeInteger(sinceTodoCalls) || sinceTodoCalls < threshold) return "";
  if (remindersSent > 0 && sinceTodoCalls - lastReminderAt < threshold) return "";
  const cur = currentInProgress(state);
  const next = nextPending(state);
  const parts: string[] = [];
  if (cur) parts.push(`正在做：#${cur.id} ${cur.text}`);
  if (next) parts.push(`下一项：#${next.id} ${next.text}`);
  const where = parts.length > 0 ? `目前清单：${parts.join("；")}。` : "";
  return `提醒：你已经连续 ${sinceTodoCalls} 次工具调用没有更新 todo 清单。${where}请先同步清单——推荐调用 todo(action="advance") 推进一项（当前项置 done、下一项置 in_progress）；需要改状态或文本时用 todo(action="update")。`;
}

/**
 * 清单陈旧提醒（纯函数）：清单仍有未完成项，且自上次 `todo` 调用以来已累计
 * `threshold`（含）次以上其它工具调用时给出提醒；否则返回空串。
 * 只在 settle 的续跑催促里注入（不在工具调用中途打断，也不额外发起模型请求）；
 * `threshold <= 0` 表示关闭该提醒。
 */
export function staleTodoNote(
  state: TodoState,
  sinceTodoCalls: number,
  threshold: number = DEFAULT_TODO_STALE_CALLS,
): string {
  if (threshold <= 0) return "";
  if (!hasOpenItems(state)) return "";
  if (!Number.isSafeInteger(sinceTodoCalls) || sinceTodoCalls < threshold) return "";
  return `提醒：你已经连续 ${sinceTodoCalls} 次工具调用没有更新 todo 清单。请先同步清单（已完成项改 done、当前正在做的项改 in_progress），再继续下一步。`;
}

/** 面向模型/终端的纯文本清单；空清单返回固定占位文案 */
export function render(state: TodoState): string {
  if (state.items.length === 0) return "（清单为空）";
  const lines = state.items.map((it) => `${MARK[it.status]} #${it.id} ${it.text}`);
  lines.push(`未完成：${openItems(state).length}/${state.items.length}`);
  return lines.join("\n");
}

/** 状态区摘要里“进行中标题”的最大显示列宽（CJK 计 2 列） */
export const SUMMARY_TITLE_MAX_COLS = 24;

/** 单个码点的显示列宽：CJK/全角/宽字符计 2，其余（含 emoji 近似）计 1 */
function codePointDisplayWidth(cp: number): number {
  if (
    (cp >= 0x1100 && cp <= 0x115f) ||
    (cp >= 0x2e80 && cp <= 0xa4cf) ||
    (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) ||
    (cp >= 0xfe30 && cp <= 0xfe4f) ||
    (cp >= 0xff00 && cp <= 0xff60) ||
    (cp >= 0xffe0 && cp <= 0xffe6) ||
    (cp >= 0x20000 && cp <= 0x3fffd)
  ) {
    return 2;
  }
  return 1;
}

/** 字符串显示列宽（CJK 按 2 列） */
export function displayWidth(text: string): number {
  let w = 0;
  for (const ch of text) w += codePointDisplayWidth(ch.codePointAt(0) ?? 0);
  return w;
}

/** 按显示列宽截断；超出上限时在末尾加省略号（省略号也占列宽） */
export function truncateDisplayWidth(text: string, maxCols: number): string {
  if (maxCols <= 0) return "";
  if (displayWidth(text) <= maxCols) return text;
  const ellipsis = "…";
  const budget = maxCols - displayWidth(ellipsis);
  if (budget <= 0) return ellipsis;
  let w = 0;
  let out = "";
  for (const ch of text) {
    const cw = codePointDisplayWidth(ch.codePointAt(0) ?? 0);
    if (w + cw > budget) break;
    out += ch;
    w += cw;
  }
  return out + ellipsis;
}

/**
 * 净化标题为单行可安全显示的文本（**外部输入校验**，标题来自模型输入的 todo 文本）：
 * 1) 去掉 ANSI 转义序列（OSC/CSI/其它 ESC），避免注入颜色/光标/窗口标题等控制码；
 * 2) 其余 C0/C1 控制字符（含 \n\r\t 与 BEL）统一转空格；
 * 3) 合并连续空格并 trim。
 * 注：Pi footer 自己的 sanitizeStatusText 只处理 \r\n\t，不剥离 ANSI，故必须在本函数内完成。
 */
function sanitizeTitle(text: string): string {
  return text
    .replace(/\u001b\][\s\S]*?(?:\u0007|\u001b\\)/g, "") // OSC … BEL/ST
    .replace(/\u001b\[[0-9;?]*[ -/]*[@-~]/g, "") // CSI（如 \x1b[31m）
    .replace(/\u001b[@-Z\\-_]/g, "") // 其它 ESC 序列
    .replace(/[\u0000-\u001f\u007f-\u009f]+/g, " ") // 剩余控制字符
    .replace(/ +/g, " ")
    .trim();
}

/** 状态区摘要片段角色（index.ts 据此上色；本模块保持纯文本、无 Pi 依赖） */
export type SummaryRole = "bar" | "count" | "active" | "warn";

export interface SummarySegment {
  role: SummaryRole;
  text: string;
}

/** 进度条格数 */
export const PROGRESS_BAR_CELLS = 4;

/** 已填格数：完成/总数 四舍五入；有任务且有完成时至少 1 格；上限 cells 格 */
export function progressFilled(done: number, total: number, cells: number = PROGRESS_BAR_CELLS): number {
  if (total <= 0 || done <= 0) return 0;
  let filled = Math.round((done / total) * cells);
  if (filled < 1) filled = 1;
  if (filled > cells) filled = cells;
  return filled;
}

/** 全部完成（有清单且所有项都是 done） */
export function isAllDone(state: TodoState): boolean {
  return state.items.length > 0 && state.items.every((it) => it.status === "done");
}

/**
 * 当前环节：第一个 `in_progress`；模型没有标记进行中时回退到第一个 `pending`；
 * 两者都没有（只剩 blocked/skipped）时返回 undefined。
 * 回退是给“模型只标 done、从不标 in_progress”的场景兜底，让 footer 仍有环节名可看。
 */
export function currentItem(state: TodoState): TodoItem | undefined {
  return (
    state.items.find((it) => it.status === "in_progress") ??
    state.items.find((it) => it.status === "pending")
  );
}

/**
 * footer 状态区摘要的分段表示（纯函数）。各片段 text 直接拼接即 formatTodoSummary：
 * - 空清单 → []（调用方清除 setStatus）；
 * - 全部完成 → `[{bar:"✓ n/n"}]`（无进度条、无标题）；
 * - 否则 → `[{bar:"▰▰▱▱"},{count:" d/t"}]` + 可选 `[{active:" ▶|▷ 标题[ +n]"}]` + 可选 `[{warn:" ⚠n"}]`。
 * 口径：`done`=status==="done"；`total`=全部条目；`skipped` 计入总数、不计完成（与 openItems 一致）；
 * `blocked` 计入 openItems（未完成）并附 ⚠；标题先净化再按显示列宽封顶。
 * 当前环节取 `currentItem()`：`in_progress` 显示 `▶`，回退到 `pending` 时显示 `▷`（一眼可辨
 * 模型没在维护“进行中”）；`+n` = 其余可作为当前环节的项数（`pending` + `in_progress` 去掉
 * 已展示的那项；`blocked`/`skipped`/`done` 不计，`blocked` 由 `⚠n` 单列）。
 */
export function summarySegments(
  state: TodoState,
  maxTitleCols: number = SUMMARY_TITLE_MAX_COLS,
): SummarySegment[] {
  if (state.items.length === 0) return [];
  const total = state.items.length;
  const done = state.items.filter((it) => it.status === "done").length;
  if (done === total) {
    return [{ role: "bar", text: `✓ ${done}/${total}` }];
  }
  const filled = progressFilled(done, total);
  const bar = "▰".repeat(filled) + "▱".repeat(PROGRESS_BAR_CELLS - filled);
  const segments: SummarySegment[] = [
    { role: "bar", text: bar },
    { role: "count", text: ` ${done}/${total}` },
  ];
  const current = currentItem(state);
  if (current) {
    const marker = current.status === "in_progress" ? "▶" : "▷";
    segments.push({
      role: "active",
      text: ` ${marker} ${truncateDisplayWidth(sanitizeTitle(current.text), maxTitleCols)}`,
    });
    const others = state.items.filter(
      (it) => it !== current && (it.status === "pending" || it.status === "in_progress"),
    ).length;
    if (others > 0) {
      segments.push({ role: "active", text: ` +${others}` });
    }
  }
  const blocked = state.items.filter((it) => it.status === "blocked").length;
  if (blocked > 0) {
    segments.push({ role: "warn", text: ` ⚠${blocked}` });
  }
  return segments;
}

/** footer 状态区摘要纯文本（= summarySegments 的拼接；无 Pi 依赖） */
export function formatTodoSummary(
  state: TodoState,
  maxTitleCols: number = SUMMARY_TITLE_MAX_COLS,
): string {
  return summarySegments(state, maxTitleCols)
    .map((s) => s.text)
    .join("");
}

// ---------- 多行 todo 面板（setWidget） ----------

/** 面板行角色；index.ts 据此用主题 API 上色 */
export type TodoWidgetRole = "header" | "active" | "blocked" | "pending" | "alldone";

export interface TodoWidgetLine {
  role: TodoWidgetRole;
  text: string;
}

export interface TodoWidgetOptions {
  /** 面板总行数上限（含 header）；默认 4 */
  maxRows?: number;
  /** 单条标题截断列宽（CJK 计 2）；默认 40 */
  titleCols?: number;
  /** 自上次 todo 调用起的其它工具调用数（用于标题陈旧标注） */
  staleCalls?: number;
  /** 陈旧标注阈值（<=0 关闭）；staleCalls >= 阈值时表头追加标注 */
  staleThreshold?: number;
}

/** 面板单条标题的默认列宽 */
export const WIDGET_TITLE_MAX_COLS = 40;
/** 面板默认总行数上限（header + 3 条明细） */
export const WIDGET_MAX_ROWS = 4;

/**
 * 多行 todo 面板（纯函数，无 Pi 依赖）。返回 [{role, text}]：
 * - 首行 header：`Todo ▰▰▱▱ 完成/总数`（进度条口径与 progressFilled/summarySegments 一致）；
 * - 已完成（done）与 skipped 折叠不展示；
 * - 按优先级依次展示：in_progress（▶）、blocked（⚠）、pending（·）；
 * - 总行数（含 header）不超过 maxRows（默认 4）= header + 最多 3 条明细；
 *   放不下的**不额外提示**（总数看 header 的 完成/总数），没有 `…还有 k 项` 行；
 * - 全部完成（done === total）→ 仅一行 alldone `✓ 全部完成 n/n`；空清单 → []；
 * - 标题先净化（sanitizeTitle：剥 ANSI、控制字符转空格、合并空格）再按 titleCols 截断；
 * - `skipped` 计入总数、不计完成（与 openItems 一致）。
 * 注：这里只限制“逻辑行数”；极窄终端下 Text 组件仍会按宽度换行，属已知显示限制。
 */
export function formatTodoWidget(
  state: TodoState,
  options: TodoWidgetOptions = {},
): TodoWidgetLine[] {
  const maxRows = options.maxRows ?? WIDGET_MAX_ROWS;
  const titleCols = options.titleCols ?? WIDGET_TITLE_MAX_COLS;
  if (maxRows <= 0) return [];
  const items = state.items;
  if (items.length === 0) return [];
  const total = items.length;
  const done = items.filter((it) => it.status === "done").length;
  if (done === total) {
    return [{ role: "alldone", text: `✓ 全部完成 ${done}/${total}` }];
  }

  const filled = progressFilled(done, total);
  const bar = "▰".repeat(filled) + "▱".repeat(PROGRESS_BAR_CELLS - filled);
  const staleThreshold = options.staleThreshold ?? 0;
  const staleCalls = options.staleCalls ?? 0;
  const stale =
    staleThreshold > 0 && Number.isSafeInteger(staleCalls) && staleCalls >= staleThreshold
      ? ` · ${staleCalls} 次调用未同步`
      : "";
  const lines: TodoWidgetLine[] = [{ role: "header", text: `Todo ${bar} ${done}/${total}${stale}` }];

  const inProgress = items.filter((it) => it.status === "in_progress");
  const blocked = items.filter((it) => it.status === "blocked");
  const pending = items.filter((it) => it.status === "pending");

  type Entry = { role: "active" | "blocked" | "pending"; item: TodoItem };
  const entries: Entry[] = [];
  // 优先级：当前工作（▶）→ 阻断（⚠）→ 待办（·）
  for (const it of inProgress) entries.push({ role: "active", item: it });
  for (const it of blocked) entries.push({ role: "blocked", item: it });
  for (const it of pending) entries.push({ role: "pending", item: it });

  // header 占 1 行；不展示 more 行，放不下的直接截断（总数见 header 的 完成/总数）。
  const capacity = Math.max(0, maxRows - 1);
  for (const e of entries.slice(0, capacity)) {
    const marker = e.role === "active" ? "▶" : e.role === "blocked" ? "⚠" : "·";
    const title = truncateDisplayWidth(sanitizeTitle(e.item.text), titleCols);
    lines.push({ role: e.role, text: `${marker} #${e.item.id} ${title}` });
  }
  return lines;
}

/**
 * 从会话分支条目中选出最后一份 Todo 快照。
 * 认两种持久化：
 *  - toolResult（toolName==="todo", details.state）：模型工具调用写入；
 *  - custom entry（customType===TODO_ENTRY_NAME, data.state）：`/todo clear` 等
 *    用户命令写入（无工具结果）。
 * 其它条目（含 compaction）一律跳过。Pi 的 `sessionManager.getBranch()` 返回完整
 * 路径（非 compaction-aware），故被压缩进 summary 的早期快照仍在分支上，清单不丢。
 */
export function selectTodoState(entries: readonly unknown[]): TodoState {
  let state = EMPTY_TODO_STATE;
  for (const entry of entries) {
    if (entry === null || typeof entry !== "object") continue;
    const e = entry as { type?: unknown; message?: unknown; customType?: unknown; data?: unknown };
    if (e.type === "custom") {
      if (e.customType !== TODO_ENTRY_NAME) continue;
      const data = e.data as { state?: unknown } | undefined;
      if (data && isTodoState(data.state)) state = data.state;
      continue;
    }
    if (e.type !== "message") continue;
    const message = e.message;
    if (message === null || typeof message !== "object") continue;
    const m = message as { role?: unknown; toolName?: unknown; details?: unknown };
    if (m.role !== "toolResult" || m.toolName !== TODO_TOOL_NAME) continue;
    const details = m.details as { state?: unknown } | undefined;
    if (details && isTodoState(details.state)) {
      state = details.state;
    }
  }
  return state;
}

