    return `pi-handoff-gate：已达最大自动续跑次数（${config.maxAutoContinue}），停止自动续跑。请检查代理状态，必要时直接输入新的指令。`;
  }
  return "pi-handoff-gate：续跑后无任何工具调用（无进展），停止自动续跑。请检查代理状态，必要时直接输入新的指令。";
}

/**
 * 读取数值 flag 并强制转换。CLI 传入的值是字符串，未传时是注册的默认值（number）；
 * 非法值回退默认值。
 */
function readFlag(pi: ExtensionAPI, name: string, fallback: number): number {
  const value = pi.getFlag(name);
  if (typeof value === "number" && Number.isSafeInteger(value) && value >= 0) {
    return value;
  }
  if (typeof value === "string") {
    const parsed = Number(value);
    if (Number.isSafeInteger(parsed) && parsed >= 0) {
      return parsed;
    }
  }
  return fallback;
}

/** --handoff-disable 为 true 时扩展完全不介入：不注入提示、不做工具判定、不续跑。 */
function isDisabled(pi: ExtensionAPI): boolean {
  return pi.getFlag(FLAG_DISABLE) === true;
}

export default function (pi: ExtensionAPI) {
  pi.registerFlag(FLAG_MAX_CONTINUE, {
    description: "pi-handoff-gate: max automatic continuations per run (default 40)",
    type: "number",
    default: DEFAULT_MAX_AUTO_CONTINUE,
